window.QBANK={"start-5858fa83": {"id": "start-5858fa83", "lesson": 0, "level": "START · ORDER", "q": "In Question 1, what is the correct order of steps for each contract?", "hint": "What does the clause promise?", "opts": [{"t": "Existence, exercise, clause triage, <abbr title=\"Anti-suit injunction\">ASI</abbr>, <abbr title=\"Singapore International Commercial Court\">SICC</abbr>", "why": "Clause triage comes first because what the clause promises decides who, if anyone, is in breach.", "ok": false}, {"t": "Clause triage, then existence, then exercise, then <abbr title=\"Singapore International Commercial Court\">SICC</abbr>, then <abbr title=\"Anti-suit injunction\">ASI</abbr>", "why": "Correct: the router's <a class=\"xref\" href=\"start.html#t-00-2\">00.2</a> template, run once per contract, with judgments only at the end.", "ok": true}, {"t": "Foreign judgments first, then each contract", "why": "Judgments come last, after all the contracts.", "ok": false}, {"t": "<abbr title=\"Anti-suit injunction\">ASI</abbr> first, because it is the most urgent remedy", "why": "The <abbr title=\"Anti-suit injunction\">ASI</abbr> is ancillary relief to the Singapore action, so it comes after jurisdiction is settled.", "ok": false}]}, "start-401c5db7": {"id": "start-401c5db7", "lesson": 0, "level": "START · CONCEPTS", "q": "What is the difference between the existence and the exercise of jurisdiction?", "hint": "Power, then discretion.", "opts": [{"t": "Existence is for contracts, exercise is for torts", "why": "Both questions arise for every claim.", "ok": false}, {"t": "Existence asks whether the court has power over the defendant at all; exercise asks whether it should use that power or send the case elsewhere", "why": "Correct: existence comes from service or submission; exercise is the stay / strong cause / Spiliada stage.", "ok": true}, {"t": "Existence is decided by the foreign court, exercise by Singapore", "why": "Singapore decides both for its own courts.", "ok": false}, {"t": "They are the same question asked twice", "why": "They are distinct, and exercise only arises once existence is shown.", "ok": false}]}, "start-bdb19922": {"id": "start-bdb19922", "lesson": 0, "level": "START · TRAPS", "q": "A contract dated 1 March 2015 contains an exclusive Singapore jurisdiction clause. Why can the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> not apply?", "hint": "Check the date the clause was made.", "opts": [{"t": "Because Singapore clauses are never covered by the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "A Singapore <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> can be a <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> case: that is <a class=\"xref\" href=\"j1.html#t-J1-3\">J1.3</a>.", "ok": false}, {"t": "Because the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> only covers non-exclusive clauses", "why": "The opposite: it covers exclusive (or deemed exclusive) clauses only.", "ok": false}, {"t": "Because the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> applies only to torts", "why": "It applies to civil or commercial matters, mainly contract.", "ok": false}, {"t": "The clause was concluded before the Hague Convention entered into force for Singapore on 1 October 2016", "why": "Correct: the temporal gateway in <a class=\"xref\" href=\"j1.html#p-J1-2-2\">J1.2.2</a>.", "ok": true}]}, "start-53c9706d": {"id": "start-53c9706d", "lesson": 0, "level": "START · CONCEPTS", "q": "Which three questions make up conflict of laws?", "hint": "Court, law, judgment.", "opts": [{"t": "Contract, tort and restitution", "why": "Those are categories of claim that choice of law sorts issues into.", "ok": false}, {"t": "Spiliada, strong cause and the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "Those are tests and regimes within the jurisdiction question.", "ok": false}, {"t": "Service in, service out and submission", "why": "Those are the ways jurisdiction exists.", "ok": false}, {"t": "Jurisdiction, choice of law, and recognition and enforcement of foreign judgments", "why": "Correct: the stadium, the rulebook and whether another league's result counts.", "ok": true}]}, "start-19659d53": {"id": "start-19659d53", "lesson": 0, "level": "START · STRUCTURE", "q": "Question 2 begins \"Assume the Singapore court will assume jurisdiction\". What should you do first?", "hint": "No J files in Q2.", "opts": [{"t": "Check whether the defendant was served in Singapore", "why": "The question has told you to assume jurisdiction.", "ok": false}, {"t": "Run Spiliada to see if Singapore is the right forum", "why": "Again, jurisdiction is assumed.", "ok": false}, {"t": "Characterise the issue under Singapore law", "why": "Correct: characterisation is the starter (<a class=\"xref\" href=\"c1.html#t-C1-1\">C1.1</a>); the jurisdiction files are not needed.", "ok": true}, {"t": "Apply the presumption of similarity to every issue", "why": "That only arises if foreign law is not proved.", "ok": false}]}, "start-be5ae470": {"id": "start-be5ae470", "lesson": 0, "level": "START · STRUCTURE", "q": "Why does Question 1 run contract by contract?", "hint": "Different clauses, different breaches.", "opts": [{"t": "Because the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> requires it", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> says nothing about exam structure.", "ok": false}, {"t": "Each contract usually has its own clause, parties and claims, so who breached what differs between contracts", "why": "Correct, and it follows Prof Chong's answer framework.", "ok": true}, {"t": "Because foreign judgments must be analysed first", "why": "Judgments come last.", "ok": false}, {"t": "Because only one contract can be governed by Singapore law", "why": "There is no such rule.", "ok": false}]}, "start-101df618": {"id": "start-101df618", "lesson": 0, "level": "START · CONCEPTS", "q": "Which test applies when a party has broken a jurisdiction clause?", "hint": "Breach changes the test.", "opts": [{"t": "Spiliada, with the burden always on the defendant", "why": "Spiliada applies where no one is in breach.", "ok": false}, {"t": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>'s s 12 exceptions", "why": "Only in a Convention case where a foreign court is chosen.", "ok": false}, {"t": "Double actionability", "why": "That is the tort choice of law rule.", "ok": false}, {"t": "Strong cause, with the burden on the party in breach", "why": "Correct (<a class=\"xref\" href=\"j4.html#t-J4-3\">J4.3</a>): the court holds parties to their bargain unless shown strong cause.", "ok": true}]}, "start-16fbe1b9": {"id": "start-16fbe1b9", "lesson": 0, "level": "START · TRAPS", "q": "The facts say \"Assume the clause is valid under English law but void under Ruritanian law.\" What is the examiner signalling?", "hint": "Assume = issue.", "opts": [{"t": "That renvoi must be applied", "why": "Renvoi is deployed only if the reference to foreign law is challenged, and its operation is off-syllabus.", "ok": false}, {"t": "That you should ignore the clause", "why": "The clause may well survive; it depends on the applicable law.", "ok": false}, {"t": "The answer turns on which law governs the clause's validity, so argue both routes and pick one", "why": "Correct: every \"Assume…\" line is an issue (<a class=\"xref\" href=\"start.html#t-00-1\">00.1</a>).", "ok": true}, {"t": "That English law always prevails in Singapore", "why": "Nothing makes English law automatically prevail.", "ok": false}]}, "start-f9d619ef": {"id": "start-f9d619ef", "lesson": 0, "level": "START · REGIMES", "q": "Which statement about <abbr title=\"Reciprocal Enforcement of Foreign Judgments Act 1959 (not examinable)\">REFJA</abbr> is right for this exam?", "hint": "Off-syllabus.", "opts": [{"t": "It must be analysed in full before the common law", "why": "It is outline only, for comparison.", "ok": false}, {"t": "It governs choice of law in tort", "why": "It concerns foreign judgments only.", "ok": false}, {"t": "It replaces the common law entirely", "why": "Even where it applies the common law question still matters for the exam; and the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> leaves the common law open.", "ok": false}, {"t": "It is not examinable, so give it one line at most and go to the common law", "why": "Correct: Prof Chong said she will not examine <abbr title=\"Reciprocal Enforcement of Foreign Judgments Act 1959 (not examinable)\">REFJA</abbr>.", "ok": true}]}, "start-8c105df6": {"id": "start-8c105df6", "lesson": 0, "level": "START · READING", "q": "In a pre-write, what does \"<span class=\"pm pm-both\">(±)</span>\" next to a point mean?", "hint": "Plus, minus, both.", "opts": [{"t": "The point is from a dissent", "why": "It says nothing about the source.", "ok": false}, {"t": "The point applies only in Question 2", "why": "It is used in every file.", "ok": false}, {"t": "The point is wrong and should be skipped", "why": "It flags a contestable point, which is where marks are.", "ok": false}, {"t": "Argue it both ways", "why": "Correct: <span class=\"pm pm-plus\">(+)</span> helps the party relying on the rule, <span class=\"pm pm-minus\">(−)</span> the other side, <span class=\"pm pm-both\">(±)</span> both.", "ok": true}]}, "start-f5265b6e": {"id": "start-f5265b6e", "lesson": 0, "level": "START · ORDER", "q": "In Question 1, where do foreign judgments come?", "hint": "End of Q1.", "opts": [{"t": "Last, after all the contracts", "why": "Correct: router <a class=\"xref\" href=\"start.html#t-00-3\">00.3</a>, \"after all contracts\".", "ok": true}, {"t": "Only in Question 2", "why": "Foreign judgments are a Question 1 topic.", "ok": false}, {"t": "First, because they may decide everything", "why": "The router puts them last.", "ok": false}, {"t": "Inside the clause triage for each contract", "why": "Only an earlier foreign ruling on the Convention's application is checked at triage (issue estoppel).", "ok": false}]}, "j1-c9cf4a4f": {"id": "j1-c9cf4a4f", "lesson": 1, "level": "J1 · REGIMES", "q": "In what order does the regime router check the three regimes?", "hint": "Which one overrides the rest?", "opts": [{"t": "Only the common law; the others are optional", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> is mandatory where it applies.", "ok": false}, {"t": "Common law, then <abbr title=\"Singapore International Commercial Court\">SICC</abbr>, then <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> displaces the common law, so it must be checked first.", "ok": false}, {"t": "<abbr title=\"Singapore International Commercial Court\">SICC</abbr>, then <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, then common law", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> decides whether Singapore must hear the case at all; the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> is about allocation within Singapore.", "ok": false}, {"t": "<abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, then <abbr title=\"Singapore International Commercial Court\">SICC</abbr>, then the common law", "why": "Correct: the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> overrides the others within its scope, so it goes first.", "ok": true}]}, "j1-5a9e281f": {"id": "j1-5a9e281f", "lesson": 1, "level": "J1 · REGIMES", "q": "What does Yeo's line \"not every Convention case will be an <abbr title=\"Singapore International Commercial Court\">SICC</abbr> case, and not every <abbr title=\"Singapore International Commercial Court\">SICC</abbr> case will be a Convention case\" mean?", "hint": "Overlapping circles.", "opts": [{"t": "The <abbr title=\"Singapore International Commercial Court\">SICC</abbr> can never hear a Convention case", "why": "A post-2016 exclusive \"Singapore High Court\" clause includes the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>.", "ok": false}, {"t": "Convention cases must be transferred to the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>", "why": "There is no such rule; the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> Rules allocate cases internally.", "ok": false}, {"t": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> and the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> have different scopes that only partly overlap", "why": "Correct: a case can be in one regime, both, or neither.", "ok": true}, {"t": "The two regimes are the same thing", "why": "They are separate regimes.", "ok": false}]}, "j1-abcf22ab": {"id": "j1-abcf22ab", "lesson": 1, "level": "J1 · PROMISES", "q": "Which promises does an exclusive jurisdiction clause contain?", "hint": "All three.", "opts": [{"t": "Submit to the chosen court, not object to it, and not sue elsewhere", "why": "Correct: (1A), (1B) and (2).", "ok": true}, {"t": "Submit and not object, but not a promise to stay away from other courts", "why": "That describes a Singapore <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr>.", "ok": false}, {"t": "Only a promise to submit", "why": "That is the minimum in a <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr>.", "ok": false}, {"t": "Only a promise not to sue elsewhere", "why": "That is derogation; an <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> also has prorogation.", "ok": false}]}, "j1-275ca7c4": {"id": "j1-275ca7c4", "lesson": 1, "level": "J1 · PROMISES", "q": "A clause says the parties \"submit to the non-exclusive jurisdiction of the courts of Hong Kong\". The claimant sues in Singapore. Who is in breach?", "hint": "Non-exclusive and foreign.", "opts": [{"t": "No one, so plain Spiliada applies", "why": "Correct: a foreign <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> has no promise not to sue elsewhere, and Singapore is not the named court (Shanghai Turbo).", "ok": true}, {"t": "The defendant, if it applies for a stay", "why": "The defendant only promised not to object to Hong Kong.", "ok": false}, {"t": "The claimant, so it must show strong cause", "why": "A <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> contains no promise (2).", "ok": false}, {"t": "Both parties", "why": "Neither has broken anything.", "ok": false}]}, "j1-2a389c65": {"id": "j1-2a389c65", "lesson": 1, "level": "J1 · NEJC", "q": "Why does a Singapore <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> carry a promise not to object, per Shanghai Turbo (<abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr>)?", "hint": "Devoid of purpose.", "opts": [{"t": "\"Submit\" means consenting and waiving objection; otherwise the clause would be devoid of purpose", "why": "Correct: the contractual approach, adopting Noble Power and Briggs.", "ok": true}, {"t": "Because the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> deems it exclusive", "why": "That is s 3(2) <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, a different regime.", "ok": false}, {"t": "Because all NEJCs are really exclusive", "why": "A <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> still has no promise (2).", "ok": false}, {"t": "Because Singapore law presumes every clause names Singapore", "why": "There is no such presumption.", "ok": false}]}, "j1-36768a5a": {"id": "j1-36768a5a", "lesson": 1, "level": "J1 · FLOATING", "q": "\"Singapore/or PRC\", with no mechanism for choosing between them. What is the clause, per Shanghai Turbo (<abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr>)?", "hint": "Both, non-exclusively.", "opts": [{"t": "A <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> to both courts, each party submitting to whichever is seised", "why": "Correct; letting the claimant elect at suit was rejected as encouraging a race to sue.", "ok": true}, {"t": "A floating choice of law clause", "why": "It concerns jurisdiction, not law.", "ok": false}, {"t": "An <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> for whichever court the claimant picks", "why": "That reading was rejected.", "ok": false}, {"t": "Void for uncertainty", "why": "It is not too uncertain to operate as a <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> to both.", "ok": false}]}, "j1-e64e6aae": {"id": "j1-e64e6aae", "lesson": 1, "level": "J1 · CCAA", "q": "A clause says \"the parties submit to the jurisdiction of the Singapore courts\", with nothing about exclusivity. Under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> it is…", "hint": "Deemed.", "opts": [{"t": "outside the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> because it is unlabelled", "why": "Unlabelled clauses are exactly what s 3(2) covers.", "ok": false}, {"t": "deemed exclusive unless the parties expressly provide otherwise (s 3(2))", "why": "Correct; at common law the same clause could go either way.", "ok": true}, {"t": "void for uncertainty", "why": "It is perfectly certain.", "ok": false}, {"t": "non-exclusive, because it does not say \"exclusive\"", "why": "s 3(2) deems it exclusive.", "ok": false}]}, "j1-b0bf5d92": {"id": "j1-b0bf5d92", "lesson": 1, "level": "J1 · CCAA", "q": "A loan's clause gives Singapore courts exclusive jurisdiction but lets the lender sue anywhere. Under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, per CHLOE V…", "hint": "Asymmetric = outside.", "opts": [{"t": "it is exclusive for the lender only", "why": "The Convention does not cover clauses exclusive for only some parties.", "ok": false}, {"t": "it is not exclusive, so s 12 cannot be engaged even if the defendant concedes it", "why": "Correct, following the Hartley–Dogauchi Report.", "ok": true}, {"t": "the court must decide the point only if a party raises it", "why": "CHLOE V said s 12 could not be engaged even on the court's own motion.", "ok": false}, {"t": "it is exclusive because the borrower is restricted", "why": "CHLOE V held otherwise.", "ok": false}]}, "j1-270dd844": {"id": "j1-270dd844", "lesson": 1, "level": "J1 · CCAA", "q": "Two Singapore companies make a contract negotiated and performed wholly in Singapore, choosing the courts of Hong Kong exclusively. Does the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> apply?", "hint": "Ignore the chosen court's location.", "opts": [{"t": "Only if Hong Kong law governs", "why": "Governing law does not decide internationality here.", "ok": false}, {"t": "Yes, because the clause is exclusive", "why": "Exclusivity is only one gateway.", "ok": false}, {"t": "No: the case is not international under s 4", "why": "Correct: same residence, everything else connected only with Singapore.", "ok": true}, {"t": "Yes, because the chosen court is foreign", "why": "The chosen court's location is ignored in the s 4 test.", "ok": false}]}, "j1-79e87d21": {"id": "j1-79e87d21", "lesson": 1, "level": "J1 · CCAA", "q": "Under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, which law decides whether the clause is valid?", "hint": "Chosen court's law.", "opts": [{"t": "The law of the chosen court's State, including its choice of law rules", "why": "Correct: one reference point that deters forum shopping.", "ok": true}, {"t": "Singapore domestic law in every case", "why": "Only where Singapore is the chosen court.", "ok": false}, {"t": "The law the claimant prefers", "why": "That would encourage forum shopping.", "ok": false}, {"t": "The law of the place the contract was signed", "why": "Not the Convention's test.", "ok": false}]}, "j1-f34a0ee0": {"id": "j1-f34a0ee0", "lesson": 1, "level": "J1 · S 12", "q": "Under s 12 <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, what standard must the defendant meet at stage 1, per 6DM?", "hint": "Better of the argument.", "opts": [{"t": "A prima facie case, as for arbitration stays", "why": "Rejected: no kompetenz-kompetenz equivalent, no supervisory appeal structure.", "ok": false}, {"t": "Beyond reasonable doubt", "why": "That is a criminal standard.", "ok": false}, {"t": "A good arguable case that there is an exclusive agreement not designating Singapore", "why": "Correct: not the arbitration prima facie standard.", "ok": true}, {"t": "Proof on the balance of probabilities", "why": "Too high; 6DM chose a good arguable case.", "ok": false}]}, "j1-2a0655f3": {"id": "j1-2a0655f3", "lesson": 1, "level": "J1 · S 12", "q": "The claimant argues that it cannot join a third party in the chosen court in State B. Does s 12(1)(c) save its Singapore action?", "hint": "Extremely serious and highly probable.", "opts": [{"t": "No: following 6DM, fragmentation is far below the manifest-injustice threshold", "why": "Correct; the test is \"very different\" from strong cause at common law.", "ok": true}, {"t": "Only if State B's law is not proved", "why": "Unproved foreign law hurts the claimant, not the defendant.", "ok": false}, {"t": "Yes, if Singapore has the closest connection", "why": "s 12 has no closest-connection test.", "ok": false}, {"t": "Yes, fragmentation is always manifest injustice", "why": "6DM rejected this.", "ok": false}]}, "j1-ce2d1a5b": {"id": "j1-ce2d1a5b", "lesson": 1, "level": "J1 · S 12", "q": "Which exception lets Singapore hear the case where war in State B means its courts have stopped functioning?", "hint": "Frustration-like.", "opts": [{"t": "(a): null and void", "why": "The clause is valid; it just cannot be performed.", "ok": false}, {"t": "(d): the agreement cannot reasonably be performed", "why": "Correct: exceptional reasons beyond the parties' control, akin to frustration.", "ok": true}, {"t": "(e): the chosen court declined", "why": "The court has not ruled; it is not functioning.", "ok": false}, {"t": "(b): incapacity", "why": "Nothing to do with capacity.", "ok": false}]}, "j1-e4a7bf5a": {"id": "j1-e4a7bf5a", "lesson": 1, "level": "J1 · SCOPE", "q": "Under Fiona Trust, as applied to jurisdiction clauses in Trisuryo and Bunge, what is presumed?", "hint": "One-stop forum.", "opts": [{"t": "Third parties are always bound", "why": "Privity points the other way.", "ok": false}, {"t": "Every claim between the parties goes to the claimant's chosen forum", "why": "The presumption follows the clause, not the claimant.", "ok": false}, {"t": "Tort claims are always outside a contractual clause", "why": "Reframing rarely escapes a widely drafted clause.", "ok": false}, {"t": "Rational businessmen want all disputes arising from their relationship decided in one forum, unless the words clearly exclude them", "why": "Correct.", "ok": true}]}, "j1-cea73c63": {"id": "j1-cea73c63", "lesson": 1, "level": "J1 · SCOPE", "q": "Contracts A and B between the same parties contain competing jurisdiction clauses. Which applies, per Bunge?", "hint": "Pith and substance.", "opts": [{"t": "Always the clause in the earlier contract", "why": "Timing is not the test.", "ok": false}, {"t": "Neither: Spiliada applies", "why": "The court applies the clause the parties objectively intended.", "ok": false}, {"t": "The clause with which the dispute has the closest connection in its \"pith and substance\"", "why": "Correct, adopting Oei Hong Leong; no extended Fiona Trust presumption.", "ok": true}, {"t": "Always the clause in the later contract", "why": "Not the test.", "ok": false}]}, "j1-0d27a042": {"id": "j1-0d27a042", "lesson": 1, "level": "J1 · SCOPE", "q": "Per VKC v VJZ, can a third party rely on an <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> under <abbr title=\"Contracts (Rights of Third Parties) Act 2001\">CRTPA</abbr> s 2(1)(b)?", "hint": "Procedural label.", "opts": [{"t": "Yes, but only if the clause is non-exclusive", "why": "Exclusivity is not the point.", "ok": false}, {"t": "No: an <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> confers a procedural, not substantive, right, so s 2(1)(b) does not apply", "why": "Correct; s 2(1)(a), s 2(3) and the equitable route were left open.", "ok": true}, {"t": "No, because third parties can never rely on any clause", "why": "Other routes remain arguable.", "ok": false}, {"t": "Yes, any term benefiting a third party is enforceable", "why": "The court distinguished EJCs.", "ok": false}]}, "j1-15bc88a1": {"id": "j1-15bc88a1", "lesson": 1, "level": "J1 · PROMISES", "q": "Which promise does a <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> never contain?", "hint": "Derogation.", "opts": [{"t": "Any promise at all", "why": "It contains at least (1A).", "ok": false}, {"t": "A promise to submit to the named court", "why": "Every <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> contains (1A).", "ok": false}, {"t": "A promise not to object to the named court", "why": "A Singapore <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> does contain this (Shanghai Turbo).", "ok": false}, {"t": "A promise not to sue in any other court", "why": "Correct: derogation (2) is what makes a clause exclusive (Bambang Sutrisno).", "ok": true}]}, "j1-266aad94": {"id": "j1-266aad94", "lesson": 1, "level": "J1 · BREACH", "q": "Clause: \"exclusively to the courts of Japan\". Alpha sues in Singapore and Beta seeks a stay. Who bears which test?", "hint": "Who broke the clause?", "opts": [{"t": "Alpha bears strong cause, because suing here breaks the promise not to sue elsewhere", "why": "Correct, whether Beta was served in or out.", "ok": true}, {"t": "Alpha bears Spiliada", "why": "Breach displaces Spiliada.", "ok": false}, {"t": "Nobody: the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> must apply", "why": "Only if every <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> gateway is met.", "ok": false}, {"t": "Beta bears Spiliada, because Beta seeks the stay", "why": "No: the clause is broken, so strong cause applies.", "ok": false}]}, "j1-5483aa3d": {"id": "j1-5483aa3d", "lesson": 1, "level": "J1 · CCAA", "q": "Singapore is the chosen court in a <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> case. Beta argues Japan is more convenient and proceedings are pending there. What follows?", "hint": "Must hear.", "opts": [{"t": "Singapore applies Spiliada with the burden on Beta", "why": "s 11(2) excludes it.", "ok": false}, {"t": "Both points are irrelevant: Singapore must hear the case unless the clause is null and void (s 11)", "why": "Correct: no <abbr title=\"Forum non conveniens (the forum is not the convenient one)\">FNC</abbr>, no lis pendens.", "ok": true}, {"t": "Singapore must stay in favour of the first-seised court", "why": "There is no lis pendens rule under s 11.", "ok": false}, {"t": "Singapore applies strong cause", "why": "s 11 also excludes strong cause.", "ok": false}]}, "j1-54010a2c": {"id": "j1-54010a2c", "lesson": 1, "level": "J1 · CCAA", "q": "Under s 12(1)(c), which of these is the sort of case that could qualify as manifest injustice?", "hint": "Clear, extremely serious, highly probable.", "opts": [{"t": "Singapore has a policy of fast adjudication", "why": "Motacus rejected the domestic-policy argument.", "ok": false}, {"t": "A related party cannot be joined there", "why": "6DM rejected fragmentation.", "ok": false}, {"t": "The chosen court is more expensive", "why": "Mere expense does not qualify.", "ok": false}, {"t": "Cogent evidence that the chosen court is not independent and no fair trial is possible there", "why": "Correct: the kind of case the Hartley–Dogauchi Report contemplates.", "ok": true}]}, "j1-ebd94415": {"id": "j1-ebd94415", "lesson": 1, "level": "J1 · VALIDITY", "q": "Beta says the contract is voidable for fraudulent misrepresentation about price, but relies on its jurisdiction clause. Per CIMB and PT Selecta…", "hint": "Infection test.", "opts": [{"t": "Beta cannot rely on a clause in a contract it attacks", "why": "CIMB held the dispute is decided under the clauses as if valid.", "ok": false}, {"t": "the clause still operates, because the fraud about price does not infect consent to the clause", "why": "Correct.", "ok": true}, {"t": "the court must decide the fraud first", "why": "The point of the rule is to avoid that.", "ok": false}, {"t": "the clause falls with the contract", "why": "Only no concluded contract at all or non est factum would infect it.", "ok": false}]}, "j1-520b73e6": {"id": "j1-520b73e6", "lesson": 1, "level": "J1 · SCOPE", "q": "What is the threshold for showing that a jurisdiction clause exists and applies, per Vinmar?", "hint": "Better of the argument.", "opts": [{"t": "A much better argument", "why": "Vinmar says it need not be a \"much better argument\".", "ok": false}, {"t": "Any arguable case", "why": "That is too low.", "ok": false}, {"t": "A good arguable case: the better of the argument", "why": "Correct; more than prima facie, less than a balance of probabilities.", "ok": true}, {"t": "Beyond reasonable doubt", "why": "Criminal standard.", "ok": false}]}, "j1-d3158e99": {"id": "j1-d3158e99", "lesson": 1, "level": "J1 · EFFECTS", "q": "Per Ace Insurance v Moose, can breach of a choice of law clause usually found an <abbr title=\"Anti-suit injunction\">ASI</abbr>?", "hint": "Declaratory.", "opts": [{"t": "Yes, if the foreign court would apply another law", "why": "That was the situation in which the <abbr title=\"Anti-suit injunction\">ASI</abbr> was refused.", "ok": false}, {"t": "Only under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> deals with choice of court agreements.", "ok": false}, {"t": "No: a choice of law clause is usually declaratory, not promissory", "why": "Correct; only very clear words make it promissory.", "ok": true}, {"t": "Yes, it is a promise to litigate only where that law applies", "why": "That is the argument that was rejected.", "ok": false}]}, "j1-103a8340": {"id": "j1-103a8340", "lesson": 1, "level": "J1 · EFFECTS", "q": "What must a claimant show to recover foreign costs as damages for breach of an <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> in Singapore, per Tradewaves?", "hint": "Can, not must.", "opts": [{"t": "That the foreign claim failed on its merits", "why": "Breach lies in suing, but recovery still needs unusual features in Singapore.", "ok": false}, {"t": "The \"unusual features\" in Union Discount v Zoller, since damages \"can\", not \"must\", be awarded", "why": "Correct.", "ok": true}, {"t": "That the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> applies", "why": "Not required.", "ok": false}, {"t": "Nothing: damages follow automatically from breach", "why": "Tradewaves rejected the \"must\" approach.", "ok": false}]}, "j1-b45908b4": {"id": "j1-b45908b4", "lesson": 1, "level": "J1 · FLOATING", "q": "Which is valid at common law, per Shanghai Turbo (<abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr>) and <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>?", "hint": "Court can float; law cannot.", "opts": [{"t": "Neither", "why": "The jurisdiction version can be valid.", "ok": false}, {"t": "A floating jurisdiction clause that is not too uncertain", "why": "Correct; a floating choice of law clause is void.", "ok": true}, {"t": "A floating choice of law clause", "why": "That is void (<a class=\"xref\" href=\"c2.html\">C2</a>).", "ok": false}, {"t": "Both, always", "why": "The law version is void.", "ok": false}]}, "j1-6231addb": {"id": "j1-6231addb", "lesson": 1, "level": "J1 · TRAPS", "q": "The facts describe a clause as \"non-exclusive\". Should you argue that s 3(2) <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> deems it exclusive?", "hint": "Express words win.", "opts": [{"t": "Yes, s 3(2) deems every clause exclusive", "why": "Only where the parties have not expressly provided otherwise.", "ok": false}, {"t": "Only in the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>", "why": "s 3(2) is a <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> rule.", "ok": false}, {"t": "Yes, if Singapore is named", "why": "The label \"non-exclusive\" displaces s 3(2) regardless.", "ok": false}, {"t": "No: where the clause is non-exclusive, the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> does not apply (Prof Chong's recurring-error warning)", "why": "Correct.", "ok": true}]}, "j2-dd3aed46": {"id": "j2-dd3aed46", "lesson": 2, "level": "J2 · BASICS", "q": "Why must even a defendant who submits still be served?", "hint": "Notice and foundation.", "opts": [{"t": "Because service decides the governing law", "why": "Service has nothing to do with choice of law.", "ok": false}, {"t": "Because service both gives notice and founds jurisdiction (O 6 r 4)", "why": "Correct.", "ok": true}, {"t": "It need not be served", "why": "O 6 r 4 requires service.", "ok": false}, {"t": "Because submission is not recognised in Singapore", "why": "Submission is s 16(1)(b) <abbr title=\"Supreme Court of Judicature Act 1969\">SCJA</abbr>.", "ok": false}]}, "j2-24f4e5d4": {"id": "j2-24f4e5d4", "lesson": 2, "level": "J2 · BASICS", "q": "Why might a claimant prefer to serve a defendant in Singapore rather than abroad, per Zoom?", "hint": "Who carries the burden.", "opts": [{"t": "Service in avoids the need for any connection to Singapore at the exercise stage", "why": "The connection still matters for a stay.", "ok": false}, {"t": "After service in, the defendant bears the burden on a stay; after service out, the claimant bears it on a forum challenge", "why": "Correct.", "ok": true}, {"t": "Service in prevents any stay", "why": "A stay can still be sought.", "ok": false}, {"t": "Service out is not allowed for companies", "why": "It is allowed with permission.", "ok": false}]}, "j2-878908f6": {"id": "j2-878908f6", "lesson": 2, "level": "J2 · PRESENCE", "q": "A Japanese executive is served at Changi Airport while in transit for three hours. Does the court have jurisdiction?", "hint": "Existence v exercise.", "opts": [{"t": "No: transit does not count as presence", "why": "Transit sufficed in the cases.", "ok": false}, {"t": "Yes: presence at service is enough, however brief (Maharanee; Colt Industries)", "why": "Correct; the fleeting visit goes to a stay, not existence.", "ok": true}, {"t": "Only with the court's permission", "why": "Service on a present individual is as of right.", "ok": false}, {"t": "Only if the dispute is connected with Singapore", "why": "No substantive connection is needed for existence.", "ok": false}]}, "j2-6c4d327a": {"id": "j2-6c4d327a", "lesson": 2, "level": "J2 · COMPANIES", "q": "A foreign company registered in Singapore stopped trading and was deregistered. What does Tao Commodity say?", "hint": "Argue both ways.", "opts": [{"t": "s 376(c) applies as before", "why": "That is <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>'s reply, not Tao.", "ok": false}, {"t": "Adams v Cape applies automatically", "why": "A deregistered company that has left will usually not be present.", "ok": false}, {"t": "The company is deemed to have submitted", "why": "Not Tao's reasoning.", "ok": false}, {"t": "s 376 is unavailable after deregistration, so the claimant must serve out", "why": "Correct; <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr> argues the plain words of s 376(c) cover it.", "ok": true}]}, "j2-a93e45fd": {"id": "j2-a93e45fd", "lesson": 2, "level": "J2 · ADAMS", "q": "Which of these is NOT one of the Adams v Cape requirements for a never-registered foreign company's presence?", "hint": "r 4 is narrower.", "opts": [{"t": "Presence for more than a minimal period", "why": "That is limb 2.", "ok": false}, {"t": "The claim must arise out of the company's Singapore business", "why": "Correct: that link is an O 7 r 4 requirement (Rosenberg), not part of presence.", "ok": true}, {"t": "A reasonably permanent fixed place of business here", "why": "That is limb 1.", "ok": false}, {"t": "The business carried on is the company's own, not a representative's", "why": "That is limb 3 (Okura).", "ok": false}]}, "j2-e9fa1773": {"id": "j2-e9fa1773", "lesson": 2, "level": "J2 · ROUTER", "q": "A company incorporated in Singapore is sued. What is the correct pairing?", "hint": "Registered office.", "opts": [{"t": "s 16(1)(b) with O 7 r 4", "why": "Submission and agent service are different routes.", "ok": false}, {"t": "s 16(1)(a)(ii) with O 8 r 1", "why": "That is service out.", "ok": false}, {"t": "s 16(1)(a)(i) with Adams v Cape", "why": "Only for a never-registered foreign company.", "ok": false}, {"t": "ss 16(2), 17(1)(c) <abbr title=\"Supreme Court of Judicature Act 1969\">SCJA</abbr> with service under s 387 <abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr> at its registered office", "why": "Correct; no Adams v Cape needed.", "ok": true}]}, "j2-7ca95afa": {"id": "j2-7ca95afa", "lesson": 2, "level": "J2 · SUBMISSION", "q": "Under Zoom, what makes a step submission?", "hint": "Only necessary or only useful.", "opts": [{"t": "Any step taken in the proceedings", "why": "Contesting jurisdiction is a step but not submission (Williams &amp; Glyn's).", "ok": false}, {"t": "Only a written statement saying \"we submit\"", "why": "Conduct can amount to submission.", "ok": false}, {"t": "Only filing a defence on the merits after judgment", "why": "Submission can happen much earlier.", "ok": false}, {"t": "It is only necessary or only useful if the jurisdiction objection had been waived or never entertained", "why": "Correct.", "ok": true}]}, "j2-7a40ab3d": {"id": "j2-7a40ab3d", "lesson": 2, "level": "J2 · SUBMISSION", "q": "The defendant asks to set aside service and, in the same summons, for a stay in the alternative. Has it submitted?", "hint": "Fall-back.", "opts": [{"t": "Yes: any stay application submits", "why": "Only a stay sought alone ordinarily submits at common law.", "ok": false}, {"t": "No: a stay as a fall-back to setting aside is not submission, the prayers being considered in sequence (Zoom; Williams)", "why": "Correct, though arguing the stay first was \"unnecessarily risky\".", "ok": true}, {"t": "Yes, because both prayers are in one summons", "why": "Being in the same summons does not matter.", "ok": false}, {"t": "Only if the stay is granted", "why": "The question is the step, not the result.", "ok": false}]}, "j2-dd99bbea": {"id": "j2-dd99bbea", "lesson": 2, "level": "J2 · SUBMISSION", "q": "A defendant's Singapore solicitors are instructed to accept service. What is the effect?", "hint": "Argue both.", "opts": [{"t": "The defendant is treated as served out", "why": "Service is in Singapore.", "ok": false}, {"t": "Nothing: solicitors cannot accept service", "why": "They can if instructed.", "ok": false}, {"t": "It is a breach of any foreign jurisdiction clause", "why": "Irrelevant to the existence question.", "ok": false}, {"t": "Arguably both submission (Rothschild) and service in under O 7 r 2(1)(d) (Shanghai Turbo; COSCO); argue both", "why": "Correct; Yeo prefers the submission reasoning.", "ok": true}]}, "j2-76a466f3": {"id": "j2-76a466f3", "lesson": 2, "level": "J2 · SUBMISSION", "q": "Is choosing Singapore law to govern the contract a submission to the Singapore courts?", "hint": "Law ≠ court.", "opts": [{"t": "Yes, if the defendant is a company", "why": "Status does not matter.", "ok": false}, {"t": "Yes, choosing a law chooses its courts", "why": "A choice of law is not a choice of court.", "ok": false}, {"t": "Only if the contract also has a <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr>", "why": "The question is about the choice of law alone.", "ok": false}, {"t": "No; by analogy with Vizcaya Partners, law plus doing business here is not even implied consent", "why": "Correct.", "ok": true}]}, "j2-940e6b9a": {"id": "j2-940e6b9a", "lesson": 2, "level": "J2 · BASICS", "q": "Which pairing correctly founds jurisdiction over an individual handed the claim at a Singapore hotel?", "hint": "Present individual.", "opts": [{"t": "s 16(1)(a)(i) <abbr title=\"Supreme Court of Judicature Act 1969\">SCJA</abbr> with personal service under O 7 r 2(1)(a)", "why": "Correct.", "ok": true}, {"t": "s 16(1)(b) with O 7 r 4", "why": "Not submission or agent service.", "ok": false}, {"t": "ss 16(2), 17(1)(c) with s 387 <abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr>", "why": "That is for Singapore companies.", "ok": false}, {"t": "s 16(1)(a)(ii) with O 8 r 1", "why": "That is service out.", "ok": false}]}, "j2-4175c763": {"id": "j2-4175c763", "lesson": 2, "level": "J2 · BASICS", "q": "When must Adams v Cape be written?", "hint": "Only one case.", "opts": [{"t": "For every company defendant", "why": "Not for Singapore companies or registered foreign companies.", "ok": false}, {"t": "Only for a never-registered foreign company served under s 16(1)(a)(i)", "why": "Correct; registered companies are served under s 387 or s 376 <abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr>.", "ok": true}, {"t": "Only on service out", "why": "Service out uses O 8, not presence.", "ok": false}, {"t": "For every individual", "why": "Individuals are present physically.", "ok": false}]}, "j2-4a1c7181": {"id": "j2-4a1c7181", "lesson": 2, "level": "J2 · PRESENCE", "q": "A claimant tricks a foreign defendant into flying to Singapore for a fake meeting, then serves him. What can the defendant do?", "hint": "Lured.", "opts": [{"t": "Nothing: presence is presence", "why": "Fraudulently induced presence is the exception.", "ok": false}, {"t": "Apply to set aside service as an abuse of process (Watkins v North American Land)", "why": "Correct.", "ok": true}, {"t": "Ask for a stay under s 12 <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> is about choice of court agreements.", "ok": false}, {"t": "Argue he has submitted", "why": "He wants the opposite.", "ok": false}]}, "j2-a19bb7ef": {"id": "j2-a19bb7ef", "lesson": 2, "level": "J2 · AGENTS", "q": "Under O 7 r 4, which is required?", "hint": "Specifically relating to the action.", "opts": [{"t": "The agent is a full-time employee", "why": "Per <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>, the agent need not be.", "ok": false}, {"t": "No permission is needed", "why": "r 4 needs permission on a without-notice summons.", "ok": false}, {"t": "The agent personally controls or manages the absent defendant's affairs specifically relating to the action", "why": "Correct (limb (b)).", "ok": true}, {"t": "The defendant has a place of business in Singapore", "why": "That is part of Adams v Cape / Rosenberg for companies.", "ok": false}]}, "j2-62d12dd5": {"id": "j2-62d12dd5", "lesson": 2, "level": "J2 · COMPANIES", "q": "Under the <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr> \"Route 1\" view, why does it matter that s 376 <abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr> itself confers jurisdiction?", "hint": "Survives deregistration.", "opts": [{"t": "It removes the need for any service", "why": "Service is still required.", "ok": false}, {"t": "It converts service in into service out", "why": "No.", "ok": false}, {"t": "It means Adams v Cape must also be shown", "why": "The opposite: no Adams v Cape is needed.", "ok": false}, {"t": "Only that view lets the claimant still use s 376(c) after the company is deregistered", "why": "Correct; both routes cover trading and ceased-but-registered companies.", "ok": true}]}, "j2-cdb42fe0": {"id": "j2-cdb42fe0", "lesson": 2, "level": "J2 · SUBMISSION", "q": "Per Williams &amp; Glyn's, what does a defendant who contests jurisdiction submit to?", "hint": "Two levels.", "opts": [{"t": "Nothing at all", "why": "It submits to the court deciding the jurisdiction question.", "ok": false}, {"t": "The jurisdiction of any court the claimant chooses", "why": "Submission is to this court.", "ok": false}, {"t": "Only the court's jurisdiction to decide jurisdiction", "why": "Correct: two levels of jurisdiction.", "ok": true}, {"t": "The court's jurisdiction over the merits", "why": "That would make every challenge self-defeating.", "ok": false}]}, "j2-c714a6c6": {"id": "j2-c714a6c6", "lesson": 2, "level": "J2 · SUBMISSION", "q": "A defendant files a striking-out application without any protest about jurisdiction. Has it submitted?", "hint": "Merits step.", "opts": [{"t": "Only if it wins", "why": "The step, not the result, matters.", "ok": false}, {"t": "No, striking out is procedural", "why": "It is a step only useful if jurisdiction is accepted.", "ok": false}, {"t": "Yes, per <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr> (Spamhaus)", "why": "Correct: a striking-out application engages the merits.", "ok": true}, {"t": "Only under <abbr title=\"Rules of Court 2021\">ROC</abbr> 2014", "why": "The common law test applies.", "ok": false}]}, "j2-56837a86": {"id": "j2-56837a86", "lesson": 2, "level": "J2 · ROC 2021", "q": "The defendant's <abbr title=\"Forum non conveniens (the forum is not the convenient one)\">FNC</abbr> stay application fails. Under <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>'s narrow reading of O 6 r 7(6), what follows?", "hint": "Narrow reading.", "opts": [{"t": "The claim is automatically dismissed", "why": "A failed stay means the case goes on.", "ok": false}, {"t": "The court must transfer to the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>", "why": "Unrelated.", "ok": false}, {"t": "The defendant submits at that point, as a stay accepts jurisdiction exists", "why": "Correct; the broad reading argues the rules protect the defendant.", "ok": true}, {"t": "Nothing ever amounts to submission under <abbr title=\"Rules of Court 2021\">ROC</abbr> 2021", "why": "That is the broad reading at its strongest, not <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>'s view.", "ok": false}]}, "j3-2d574202": {"id": "j3-2d574202", "lesson": 3, "level": "J3 · FRAMEWORK", "q": "Which three requirements must a claimant meet on the \"appropriate court\" ground?", "hint": "Nexus, forum, merits.", "opts": [{"t": "Strong cause, Spiliada and the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "Different tests.", "ok": false}, {"t": "A balance of probabilities on nexus, merits and forum", "why": "Too high on nexus and merits.", "ok": false}, {"t": "A good arguable case of nexus, Singapore as forum conveniens, and a serious question to be tried", "why": "Correct: PD para 63(2), restating Zoom.", "ok": true}, {"t": "Presence, submission and a jurisdiction clause", "why": "Those are routes to existence, not the service-out test.", "ok": false}]}, "j3-7d89be53": {"id": "j3-7d89be53", "lesson": 3, "level": "J3 · FRAMEWORK", "q": "The defendant applies to set aside service out. Who bears the legal burden on the three requirements?", "hint": "Existence.", "opts": [{"t": "The defendant, because it brought the application", "why": "Setting aside attacks existence, so the burden stays on the claimant.", "ok": false}, {"t": "Nobody: the court decides afresh", "why": "The burden remains on the claimant.", "ok": false}, {"t": "The defendant on forum, the claimant on nexus", "why": "Only a stay after valid service puts stage 1 on the defendant.", "ok": false}, {"t": "The claimant, throughout (Zoom; Li Shengwu)", "why": "Correct, though in practice it becomes harder once contested.", "ok": true}]}, "j3-5e2fabf1": {"id": "j3-5e2fabf1", "lesson": 3, "level": "J3 · FRAMEWORK", "q": "A claimant brings a contract claim and a tort claim against a foreign defendant. How many para 63(3) factors must it show?", "hint": "Per claim, per defendant.", "opts": [{"t": "One factor for the whole action", "why": "Distinct claims cannot be pooled.", "ok": false}, {"t": "Two factors for each claim", "why": "One suffices, the factors being disjunctive.", "ok": false}, {"t": "One for each claim: the contract claim and the tort claim each need a factor (IM Skaugen (<abbr title=\"Court of Appeal (or, after &#x27;s&#x27;, the Companies Act 1967)\">CA</abbr>))", "why": "Correct; one factor per claim is enough.", "ok": true}, {"t": "None, if the contract has a Singapore governing law", "why": "That itself is a factor ((d)(iii)) for the contract claim only.", "ok": false}]}, "j3-49832ea6": {"id": "j3-49832ea6", "lesson": 3, "level": "J3 · FACTORS", "q": "Which para 63(3) factor depends on the defendant, not the claim?", "hint": "Catch-all.", "opts": [{"t": "(e): breach here", "why": "(e) depends on where the breach occurred.", "ok": false}, {"t": "(f): tort", "why": "(f) depends on where the tortious act or damage occurred.", "ok": false}, {"t": "(a): domicile, ordinary residence, carrying on business or property here", "why": "Correct; so contract, tort and restitution claims can all go under (a).", "ok": true}, {"t": "(d): contract", "why": "(d) depends on the contract's link to Singapore.", "ok": false}]}, "j3-8631508f": {"id": "j3-8631508f", "lesson": 3, "level": "J3 · FACTORS", "q": "A Singapore company's Singapore bank account did not receive a payment the foreign defendant owed. Is that \"damage in Singapore\" under (f)(ii)?", "hint": "Effects ≠ damage.", "opts": [{"t": "No, per Nippon Catalyst: that is not enough", "why": "Correct; distinguish incurring the loss from its effects felt here.", "ok": true}, {"t": "Yes, if the sum is large", "why": "Size is not the point.", "ok": false}, {"t": "Yes, any loss felt by a Singapore company counts", "why": "Effects felt here are not enough.", "ok": false}, {"t": "Only if the contract is governed by Singapore law", "why": "That is (d)(iii), a different factor.", "ok": false}]}, "j3-439942b3": {"id": "j3-439942b3", "lesson": 3, "level": "J3 · FACTORS", "q": "A contract can be performed in Singapore or in Thailand, and the defendant does not perform. Is there a breach \"in Singapore\" under (e)?", "hint": "Alternative places.", "opts": [{"t": "Only if the defendant repudiated in Singapore", "why": "Repudiation is relevant but not the rule here.", "ok": false}, {"t": "No: where the obligation could be performed in either place, non-performance is not a breach in Singapore (<abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>, citing Recovery Vehicle 1)", "why": "Correct.", "ok": true}, {"t": "Yes, because the claimant is in Singapore", "why": "The claimant's location does not fix the place of breach.", "ok": false}, {"t": "Yes, if Singapore law governs", "why": "The governing law is a separate factor.", "ok": false}]}, "j3-59e6a9e9": {"id": "j3-59e6a9e9", "lesson": 3, "level": "J3 · FACTORS", "q": "Per Vizcaya Partners (adopted by <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>), does a Singapore governing law clause amount to a Singapore jurisdiction term under (d)(iv)?", "hint": "Law ≠ court.", "opts": [{"t": "No: an agreement to submit is not inferred from a governing law clause", "why": "Correct; the clause itself must give Singapore jurisdiction.", "ok": true}, {"t": "Yes, choosing a law implies choosing its courts", "why": "It does not.", "ok": false}, {"t": "Yes, if the defendant does business here", "why": "Vizcaya rejected even that combination as implied consent.", "ok": false}, {"t": "Only in the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>", "why": "Irrelevant.", "ok": false}]}, "j3-1bb0d0ed": {"id": "j3-1bb0d0ed", "lesson": 3, "level": "J3 · MERITS", "q": "For which factor must the claimant prove a serious question separately?", "hint": "Neutral factors.", "opts": [{"t": "(a), because it is a neutral connecting factor about the defendant", "why": "Correct (Bradley Lomas; <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>); also (r), (d) and (c).", "ok": true}, {"t": "(p), cause of action arose here", "why": "Ordinarily (p) engages the merits.", "ok": false}, {"t": "(e), breach in Singapore", "why": "(e) engages the merits, so (c) is subsumed.", "ok": false}, {"t": "(f), tort in Singapore", "why": "(f) engages the merits.", "ok": false}]}, "j3-4a823ac2": {"id": "j3-4a823ac2", "lesson": 3, "level": "J3 · R 1(3)", "q": "A contract chooses English law, refers disputes to the Singapore courts and provides for service by registered mail. Does the claimant need approval to post the claim to Hong Kong?", "hint": "Allowed under a contract.", "opts": [{"t": "Yes, because English law governs", "why": "The governing law does not matter here.", "ok": false}, {"t": "No: O 8 r 1(3), as read widely in NW Corp", "why": "Correct.", "ok": true}, {"t": "Only if the defendant consents again at the time", "why": "The contract is the consent.", "ok": false}, {"t": "Yes, every service out needs approval", "why": "r 1(3) is the exception.", "ok": false}]}, "j3-e1e03f52": {"id": "j3-e1e03f52", "lesson": 3, "level": "J3 · MODE", "q": "A defendant moved to Dubai years before the claim was issued. Can the claimant go straight to substituted service by email?", "hint": "Hierarchy.", "opts": [{"t": "No: per Consistel it must first seek approval to serve out, and substituted service arises only if personal service is impracticable", "why": "Correct.", "ok": true}, {"t": "Yes, email is quicker", "why": "The hierarchy must be adhered to.", "ok": false}, {"t": "Yes, if the email reaches the defendant", "why": "Not retrospective.", "ok": false}, {"t": "Yes, under COSCO", "why": "Chong says COSCO is wrong; Consistel is the framework.", "ok": false}]}, "j3-46c214b0": {"id": "j3-46c214b0", "lesson": 3, "level": "J3 · THRESHOLD", "q": "Per Prof Chong, what is the best analysis when a foreign defendant authorises Singapore solicitors to accept service?", "hint": "Submission.", "opts": [{"t": "It has no effect", "why": "It does found jurisdiction one way or another.", "ok": false}, {"t": "It is service out under O 8 r 1(3)", "why": "There is no contract allowing service out.", "ok": false}, {"t": "It is submission under s 16(1)(b), a waiver of the O 8 hoops, not deemed presence", "why": "Correct; COSCO treated it as service in.", "ok": true}, {"t": "It is constructive presence because solicitors carry on its business here", "why": "Solicitors do not carry on the defendant's business (Adams v Cape).", "ok": false}]}, "j3-15fe560e": {"id": "j3-15fe560e", "lesson": 3, "level": "J3 · GROUNDS", "q": "Which approval ground does Chong's answer scheme use for the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> contract?", "hint": "<abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>.", "opts": [{"t": "No approval is ever needed for a <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> case", "why": "Only if the contract allows service out (r 1(3)).", "ok": false}, {"t": "\"Has the jurisdiction\" under O 8 r 1(1)", "why": "Correct; outside the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, use \"appropriate court\".", "ok": true}, {"t": "<abbr title=\"Singapore International Commercial Court\">SICC</abbr> Rules O 5 r 6 only", "why": "That is for the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> route.", "ok": false}, {"t": "\"Appropriate court\", with full Spiliada", "why": "A <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> chosen court cannot decline for forum non conveniens.", "ok": false}]}, "j3-48d4e0d6": {"id": "j3-48d4e0d6", "lesson": 3, "level": "J3 · FACTORS", "q": "A claimant sues D1 in Singapore only to bring in D2 abroad under (c). Is that fatal?", "hint": "Device test.", "opts": [{"t": "Yes, because (c) is abolished", "why": "(c) remains, though anomalous.", "ok": false}, {"t": "No, and D1 need not even be served", "why": "D1 must be duly served.", "ok": false}, {"t": "Yes, always: D1 must be a genuine target", "why": "The motive alone is not fatal.", "ok": false}, {"t": "No, per AK Investment, unless the claim against D1 is bound to fail", "why": "Correct (The Brabo; Derby v Larsson).", "ok": true}]}, "j3-c21e9bee": {"id": "j3-c21e9bee", "lesson": 3, "level": "J3 · FACTORS", "q": "What does Li Shengwu say about \"any other written law\" in factor (n)?", "hint": "Any means any.", "opts": [{"t": "It bears its plain meaning: any Singapore statute, ejusdem generis being rejected", "why": "Correct.", "ok": true}, {"t": "Only crime-related statutes like the CDSA and TSOFA", "why": "That narrow reading was rejected.", "ok": false}, {"t": "Foreign statutes too", "why": "It is confined to Singapore law.", "ok": false}, {"t": "Only statutes conferring subject-matter jurisdiction", "why": "s 18 and Sch 1 confer powers, a separate point.", "ok": false}]}, "j3-3c76e2dd": {"id": "j3-3c76e2dd", "lesson": 3, "level": "J3 · FORUM", "q": "On service out, what standard does Oro Negro set for forum conveniens?", "hint": "Hair or mile.", "opts": [{"t": "Forum is irrelevant on service out", "why": "It is requirement (b).", "ok": false}, {"t": "Singapore must be the only available forum", "why": "Too high.", "ok": false}, {"t": "Singapore need only be \"on balance\" the more appropriate forum, \"whether by a hair or by a mile\"", "why": "Correct; cite it alongside \"clearly\" (Spiliada; Sudarga).", "ok": true}, {"t": "Singapore must be \"clearly\" more appropriate, with no softer standard available", "why": "\"Clearly\" is the traditional reading (Spiliada; AK Investment); Oro Negro softened it to \"on balance\".", "ok": false}]}, "j3-033a558c": {"id": "j3-033a558c", "lesson": 3, "level": "J3 · R 1(3)", "q": "After valid service under O 8 r 1(3), what can the defendant still challenge?", "hint": "Exercise only.", "opts": [{"t": "Nothing at all", "why": "A stay remains possible.", "ok": false}, {"t": "Only the exercise of jurisdiction, on natural forum grounds, with the burden on itself (NW Corp)", "why": "Correct; with a Singapore court clause, strong cause.", "ok": true}, {"t": "Only the mode of service", "why": "It can seek a stay.", "ok": false}, {"t": "Existence, with the burden on the claimant", "why": "Service under r 1(3) founds jurisdiction without approval.", "ok": false}]}, "j3-0b0aea4e": {"id": "j3-0b0aea4e", "lesson": 3, "level": "J3 · CLAUSE", "q": "The claimant sues here despite an <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> for Ruritania and serves out. What must it show without notice?", "hint": "Breach by the claimant.", "opts": [{"t": "Nothing: the clause is irrelevant to service out", "why": "It changes the forum limb.", "ok": false}, {"t": "Plain Spiliada with the burden on the defendant", "why": "Breach puts strong cause on the claimant.", "ok": false}, {"t": "Only that the clause is invalid", "why": "It can rely on a different factor and strong cause.", "ok": false}, {"t": "A nexus through another factor, a serious question, and strong cause instead of forum conveniens", "why": "Correct, with the burden on the claimant throughout.", "ok": true}]}, "j3-be4cc6cd": {"id": "j3-be4cc6cd", "lesson": 3, "level": "J3 · STRATEGY", "q": "Why should a defendant served out usually apply to set aside rather than seek a stay?", "hint": "Burden.", "opts": [{"t": "Because on a set-aside the burden stays on the claimant, while on a stay the defendant bears stage 1", "why": "Correct (Zoom; <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>).", "ok": true}, {"t": "Because a stay is unavailable after service out", "why": "A stay is available.", "ok": false}, {"t": "Because a stay is always submission", "why": "A fall-back stay is not submission, but it takes on a burden.", "ok": false}, {"t": "Because set-aside applications are cheaper", "why": "Cost is not the reason.", "ok": false}]}, "j4-78fb16ac": {"id": "j4-78fb16ac", "lesson": 4, "level": "J4 · BURDEN", "q": "The defendant was served in Singapore. There is no jurisdiction clause. It seeks a stay. Who bears the stage 1 burden?", "hint": "Served in, no breach.", "opts": [{"t": "The defendant", "why": "Correct: it must show another forum is clearly more appropriate (Spiliada; JIO).", "ok": true}, {"t": "The claimant", "why": "The claimant bears stage 2, not stage 1.", "ok": false}, {"t": "The party who sued first abroad", "why": "Who sued first is not the test.", "ok": false}, {"t": "Neither: the court decides alone", "why": "Spiliada allocates the burdens.", "ok": false}]}, "j4-5545eff1": {"id": "j4-5545eff1", "lesson": 4, "level": "J4 · BURDEN", "q": "A contract has a Singapore <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> governed by Singapore law. The defendant, served out, applies to set aside on forum grounds. What test and burden apply?", "hint": "Who broke a promise?", "opts": [{"t": "Strong cause, on the defendant, because objecting breaks its promise not to object (Shanghai Turbo)", "why": "Correct.", "ok": true}, {"t": "Spiliada with the burden on the defendant", "why": "Breach displaces Spiliada.", "ok": false}, {"t": "Spiliada with the burden on the claimant", "why": "That would apply to a foreign <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> or no clause.", "ok": false}, {"t": "No test: a <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> has no effect", "why": "A Singapore <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr> contains a waiver of objection.", "ok": false}]}, "j4-ad5fb289": {"id": "j4-ad5fb289", "lesson": 4, "level": "J4 · BURDEN", "q": "A clause gives Japanese courts exclusive jurisdiction. The claimant sues in Singapore; the defendant seeks a stay. Who must show strong cause?", "hint": "Who sued in breach?", "opts": [{"t": "Nobody: the stay is automatic", "why": "There is a discretion, but strong cause is hard to show.", "ok": false}, {"t": "The claimant, because it breached the clause by suing here", "why": "Correct: the reversal.", "ok": true}, {"t": "Both, equally", "why": "Only the party in breach.", "ok": false}, {"t": "The defendant, because it applied for the stay", "why": "The application does not decide the burden; breach does.", "ok": false}]}, "j4-5d673a86": {"id": "j4-5d673a86", "lesson": 4, "level": "J4 · SPILIADA", "q": "Witnesses are in Indonesia, but they are the defendant's own employees and can testify by video. How much does this weigh at stage 1?", "hint": "Compellability &gt; convenience.", "opts": [{"t": "Little: convenience is weak given video-link, especially for a nearby forum, and employees raise no real compellability problem", "why": "Correct (JIO; Chan Chin Cheung; Chong's feedback).", "ok": true}, {"t": "It is irrelevant to Spiliada", "why": "It is relevant but light.", "ok": false}, {"t": "It points to Singapore", "why": "It points weakly to Indonesia, if at all.", "ok": false}, {"t": "It is decisive for a stay", "why": "Witness convenience is rarely decisive.", "ok": false}]}, "j4-bb3383a0": {"id": "j4-bb3383a0", "lesson": 4, "level": "J4 · SPILIADA", "q": "At stage 2, the claimant shows damages in the foreign forum would be one third of a Singapore award. Is that enough?", "hint": "Ordinary differences.", "opts": [{"t": "Yes, if the claimant is Singaporean", "why": "Nationality is not the test.", "ok": false}, {"t": "No: a legitimate juridical advantage alone is not conclusive (Chong's feedback; Goh Suan Hee)", "why": "Correct; ordinary differences in remedies are disregarded.", "ok": true}, {"t": "Yes, any lower award is injustice", "why": "That would make every stay fail.", "ok": false}, {"t": "Only if the foreign forum is a tribunal", "why": "Irrelevant.", "ok": false}]}, "j4-a69d8365": {"id": "j4-a69d8365", "lesson": 4, "level": "J4 · SPILIADA", "q": "What does \"quality, not quantity\" mean for stage 1?", "hint": "No balance sheet.", "opts": [{"t": "More factors always win", "why": "That is the balance-sheet approach rejected.", "ok": false}, {"t": "The court weighs only links relevant to the dispute, not a balance sheet of tenuous contacts (Rappo; JIO)", "why": "Correct.", "ok": true}, {"t": "Only the governing law counts", "why": "It is one factor among many.", "ok": false}, {"t": "The claimant's home always wins", "why": "Domicile weighs little in commerce.", "ok": false}]}, "j4-05133b18": {"id": "j4-05133b18", "lesson": 4, "level": "J4 · SPILIADA", "q": "Is a foreign court \"available\" if it would need permission to serve out on the defendant?", "hint": "Legal availability.", "opts": [{"t": "Not unless the defendant undertakes to submit or permission would be granted (Hindocha)", "why": "Correct.", "ok": true}, {"t": "Yes, always", "why": "Hindocha says otherwise.", "ok": false}, {"t": "That question goes to stage 2", "why": "Legal availability is a threshold point.", "ok": false}, {"t": "Only if the foreign court is in a Contracting State", "why": "Irrelevant to availability.", "ok": false}]}, "j4-16090836": {"id": "j4-16090836", "lesson": 4, "level": "J4 · STRONG CAUSE", "q": "The defendant argues the claimant has no real case on the merits, so the claimant should not be allowed to keep the case in the chosen forum. Per Vinmar…", "hint": "Win or lose there.", "opts": [{"t": "a weak claim is strong cause", "why": "That was The Jian He's approach, overruled.", "ok": false}, {"t": "the merits matter only for a <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr>", "why": "They are irrelevant for both.", "ok": false}, {"t": "the merits are irrelevant: parties choose a forum to win or lose there", "why": "Correct; Vinmar overruled The Jian He on this.", "ok": true}, {"t": "the court must decide the merits first", "why": "That breeds uncertainty, cost and delay.", "ok": false}]}, "j4-aba506c5": {"id": "j4-aba506c5", "lesson": 4, "level": "J4 · STRONG CAUSE", "q": "Which is most likely to amount to strong cause?", "hint": "Unforeseeable denial of justice.", "opts": [{"t": "Witnesses are in another country", "why": "Foreseeable; factor (a) rarely suffices.", "ok": false}, {"t": "The chosen court has been dissolved because of an unforeseen war", "why": "Correct: denial of justice, unforeseeable (Vinmar).", "ok": true}, {"t": "Foreign law governs and differs from Singapore law", "why": "Foreseeable; factor (b).", "ok": false}, {"t": "The chosen court is notoriously slow", "why": "Foreseeable at contracting.", "ok": false}]}, "j4-4f2c462d": {"id": "j4-4f2c462d", "lesson": 4, "level": "J4 · STRONG CAUSE", "q": "In Trisuryo, why was strong cause shown?", "hint": "No remedy at all.", "opts": [{"t": "The claim was illegal in Indonesia", "why": "Foreign illegality goes to the merits, not the stay.", "ok": false}, {"t": "The Indonesian court was slow", "why": "Not the reason.", "ok": false}, {"t": "Indonesian law would not recognise the trust over Indonesian shares, so the claimant could get no remedy there", "why": "Correct; it was exceptional.", "ok": true}, {"t": "The defendant's witnesses were in Singapore", "why": "Not the reason.", "ok": false}]}, "j4-da9ec93e": {"id": "j4-da9ec93e", "lesson": 4, "level": "J4 · TESTS", "q": "When does Spiliada apply rather than strong cause?", "hint": "No breach.", "opts": [{"t": "Whenever the defendant seeks a stay", "why": "A defendant can seek a stay in a strong cause case too.", "ok": false}, {"t": "When no one has broken a jurisdiction clause: no clause, a foreign <abbr title=\"Non-exclusive jurisdiction clause\">NEJC</abbr>, or a claim outside the clause", "why": "Correct (<a class=\"xref\" href=\"j4.html#p-J4-0-2\">J4.0.2</a>).", "ok": true}, {"t": "Only on service out", "why": "Spiliada applies to stays after service in as well.", "ok": false}, {"t": "Only in <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> cases", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> leaves no discretion.", "ok": false}]}, "j4-a1bcbb8e": {"id": "j4-a1bcbb8e", "lesson": 4, "level": "J4 · SPILIADA", "q": "The factors connecting the dispute are scattered across Singapore, Malaysia and Thailand, and are finely balanced. The defendant seeks a stay in favour of Malaysia. Result?", "hint": "Clearly more appropriate.", "opts": [{"t": "No stay: the defendant has not shown Malaysia is clearly more appropriate (JIO)", "why": "Correct.", "ok": true}, {"t": "The court picks whichever forum the claimant prefers", "why": "The test is not claimant-centric.", "ok": false}, {"t": "Stay in favour of Thailand", "why": "The defendant must prove its own chosen forum.", "ok": false}, {"t": "Stay, because Singapore has few links", "why": "Few links is not enough; the test is comparative.", "ok": false}]}, "j4-0e8ae4c2": {"id": "j4-0e8ae4c2", "lesson": 4, "level": "J4 · SPILIADA", "q": "What does relativity mean in JIO?", "hint": "Singapore v X.", "opts": [{"t": "Only relative costs matter", "why": "Costs are only one factor.", "ok": false}, {"t": "The comparison is Singapore against the foreign forum, so a third country's law or claim does not help the claimant", "why": "Correct.", "ok": true}, {"t": "The claimant always wins ties", "why": "Ties mean no stay, but that is a different point.", "ok": false}, {"t": "Each factor is weighed relative to the claimant's home", "why": "Not the meaning.", "ok": false}]}, "j4-9a8c7071": {"id": "j4-9a8c7071", "lesson": 4, "level": "J4 · SERVICE OUT", "q": "On service out, can the claimant succeed by showing Singapore is as appropriate as the foreign forum?", "hint": "The, not a.", "opts": [{"t": "Yes, ties go to the claimant", "why": "That is the stay position, not service out.", "ok": false}, {"t": "No: it must show Singapore is the more appropriate forum, not one of several equal fora (Sudarga)", "why": "Correct.", "ok": true}, {"t": "Only if the defendant seeks a stay", "why": "On a stay the burden is on the defendant, a different question.", "ok": false}, {"t": "Yes, if Singapore law governs", "why": "Governing law is one factor only.", "ok": false}]}, "j4-e75b620c": {"id": "j4-e75b620c", "lesson": 4, "level": "J4 · STRONG CAUSE", "q": "Under a Singapore <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr>, the defendant objects to Singapore. How are Eleftheria factors (d) and (e) used?", "hint": "Flip.", "opts": [{"t": "Flipped: is the claimant's seising abusive, or would the defendant be prejudiced defending in Singapore?", "why": "Correct (Shanghai Turbo; Vinmar).", "ok": true}, {"t": "They are dropped entirely", "why": "(a)–(c) stay, and (d)–(e) are flipped.", "ok": false}, {"t": "They become Spiliada stage 2", "why": "Strong cause is not Spiliada.", "ok": false}, {"t": "Unchanged: is the defendant acting abusively?", "why": "That is the original framing for a suit here in breach of a foreign clause.", "ok": false}]}, "j4-20b7cbf7": {"id": "j4-20b7cbf7", "lesson": 4, "level": "J4 · STRONG CAUSE", "q": "The claimant sued in Singapore in breach of a foreign <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> and is now out of time in the chosen court. Is that strong cause?", "hint": "Protective writ.", "opts": [{"t": "Only under the <abbr title=\"Foreign Limitation Periods Act 2012\">FLPA</abbr>", "why": "The point is about strong cause, not the <abbr title=\"Foreign Limitation Periods Act 2012\">FLPA</abbr>.", "ok": false}, {"t": "Only if it shows \"very good reasons\" for not filing a protective writ there; otherwise the bar is self-induced (Vinmar)", "why": "Correct.", "ok": true}, {"t": "No, time bars are never relevant", "why": "They are relevant with very good reasons.", "ok": false}, {"t": "Yes, a time bar is always strong cause", "why": "Vinmar requires very good reasons.", "ok": false}]}, "j4-b976a324": {"id": "j4-b976a324", "lesson": 4, "level": "J4 · SICC", "q": "Can the possibility of transfer to the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> alone keep a German-law fraud claim in Singapore?", "hint": "Discount, not decisive.", "opts": [{"t": "The <abbr title=\"Singapore International Commercial Court\">SICC</abbr> factor is irrelevant", "why": "Rappo says the court must not shut its eyes to it.", "ok": false}, {"t": "Yes, if the claimant asks for it", "why": "The claimant must also name a suitable <abbr title=\"Singapore International Commercial Court\">SICC</abbr> feature (Rappo).", "ok": false}, {"t": "Yes, the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> can apply any foreign law", "why": "That is not enough to displace the natural forum.", "ok": false}, {"t": "No: per IM Skaugen it is at most a discount on the weight of foreign law, never decisive alone", "why": "Correct.", "ok": true}]}, "j4-84a84737": {"id": "j4-84a84737", "lesson": 4, "level": "J4 · OVERLAYS", "q": "The claimant sues the defendant in Singapore and in Hong Kong on the same issues, and the defendant asks for both an <abbr title=\"Forum non conveniens (the forum is not the convenient one)\">FNC</abbr> stay and forum election. Which is decided first?", "hint": "<abbr title=\"Forum non conveniens (the forum is not the convenient one)\">FNC</abbr> first.", "opts": [{"t": "The <abbr title=\"Forum non conveniens (the forum is not the convenient one)\">FNC</abbr> stay; election follows only if Hong Kong is not clearly more appropriate (Rappo)", "why": "Correct.", "ok": true}, {"t": "Election first, always", "why": "Rappo puts <abbr title=\"Forum non conveniens (the forum is not the convenient one)\">FNC</abbr> first.", "ok": false}, {"t": "They are decided at trial", "why": "They are decided at the outset.", "ok": false}, {"t": "Neither: the first-seised court wins", "why": "There is no first-seised rule.", "ok": false}]}, "j5-4ea91239": {"id": "j5-4ea91239", "lesson": 5, "level": "J5 · ROUTE 1", "q": "A clause concluded in 2019 says disputes go to \"the Singapore High Court\". Can the claimant file directly in the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>?", "hint": "Check the date.", "opts": [{"t": "Yes: under O 2 r 2(1) a post-1 October 2016 High Court clause includes the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> unless a contrary intention appears", "why": "Correct; Chong's answer scheme flags that arguably a more specific reference is needed.", "ok": true}, {"t": "No: it must sue in the General Division and seek a transfer", "why": "That is for pre-2016 clauses.", "ok": false}, {"t": "Only if the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> applies", "why": "O 2 r 2(1) is not limited to <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> cases.", "ok": false}, {"t": "Only with every party's consent", "why": "Consent is a transfer requirement in <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> cases.", "ok": false}]}, "j5-86f21e13": {"id": "j5-86f21e13", "lesson": 5, "level": "J5 · ROUTE 1", "q": "An <abbr title=\"Singapore International Commercial Court\">SICC</abbr> clause is silent on exclusivity, the case is outside the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, and Singapore law governs the clause. Is it exclusive?", "hint": "Singapore law governs.", "opts": [{"t": "Only if a foreign court agrees", "why": "Singapore decides under s 18F.", "ok": false}, {"t": "Yes: s 18F applies and presumes exclusivity absent express contrary words", "why": "Correct.", "ok": true}, {"t": "No: silence means non-exclusive", "why": "s 18F reverses that default.", "ok": false}, {"t": "The question is debated even here", "why": "The debate is only where foreign law governs a non-CCAA clause.", "ok": false}]}, "j5-a979bcb7": {"id": "j5-a979bcb7", "lesson": 5, "level": "J5 · ROUTE 1", "q": "If an <abbr title=\"Singapore International Commercial Court\">SICC</abbr> clause gives primary jurisdiction over the claim, should you discuss transfer?", "hint": "Primary ends it.", "opts": [{"t": "Yes, because transfer is the main source of <abbr title=\"Singapore International Commercial Court\">SICC</abbr> cases", "why": "That is true statistically (<abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>) but irrelevant where primary jurisdiction exists.", "ok": false}, {"t": "Yes, always discuss transfer as well", "why": "Wastes time on what is not in issue.", "ok": false}, {"t": "No: per Chong, transfer matters only for a party or claim outside the clause", "why": "Correct.", "ok": true}, {"t": "Only if the defendant objects", "why": "The point is that primary jurisdiction ends the inquiry.", "ok": false}]}, "j5-3cd3da9c": {"id": "j5-3cd3da9c", "lesson": 5, "level": "J5 · NATURE", "q": "Which statement about the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> is correct?", "hint": "National court.", "opts": [{"t": "Appeals go to an international panel", "why": "They go to the Court of Appeal.", "ok": false}, {"t": "Jurisdiction over the defendant no longer needs service", "why": "Service under s 16 <abbr title=\"Supreme Court of Judicature Act 1969\">SCJA</abbr> is still needed.", "ok": false}, {"t": "It is a division of the General Division, so its judgments are Singapore High Court judgments", "why": "Correct (s 18A <abbr title=\"Supreme Court of Judicature Act 1969\">SCJA</abbr>).", "ok": true}, {"t": "It is an arbitral institution", "why": "It is a national court.", "ok": false}]}, "j5-65baccf2": {"id": "j5-65baccf2", "lesson": 5, "level": "J5 · NATURE", "q": "Which <abbr title=\"Singapore International Commercial Court\">SICC</abbr> feature lets it decide foreign law without expert evidence?", "hint": "Submissions.", "opts": [{"t": "s 18D(3)", "why": "That concerns joinder.", "ok": false}, {"t": "s 18F <abbr title=\"Supreme Court of Judicature Act 1969\">SCJA</abbr>", "why": "That presumes exclusivity.", "ok": false}, {"t": "O 2 r 3", "why": "That is the exercise test.", "ok": false}, {"t": "s 18L <abbr title=\"Supreme Court of Judicature Act 1969\">SCJA</abbr>: foreign law may be decided on submissions", "why": "Correct.", "ok": true}]}, "j5-1c72eae1": {"id": "j5-1c72eae1", "lesson": 5, "level": "J5 · EXERCISE", "q": "Under a written <abbr title=\"Singapore International Commercial Court\">SICC</abbr> agreement, the defendant shows that every witness and document is in Indonesia. Will the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> decline?", "hint": "Connections irrelevant.", "opts": [{"t": "Yes, under Spiliada", "why": "Spiliada does not apply in the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> with a written agreement.", "ok": false}, {"t": "Only if strong cause is shown", "why": "Strong cause does not apply either.", "ok": false}, {"t": "No: it must not decline solely because the action is connected to another jurisdiction (O 2 r 3(3))", "why": "Correct; no Spiliada balancing.", "ok": true}, {"t": "Yes, if the clause is non-exclusive", "why": "The 2021 Rules apply the same test to EJCs and NEJCs.", "ok": false}]}, "j5-2a824d98": {"id": "j5-2a824d98", "lesson": 5, "level": "J5 · EXERCISE", "q": "On what grounds may the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> decline jurisdiction under O 2 r 3(2)?", "hint": "Character or abuse.", "opts": [{"t": "Another forum is clearly more appropriate", "why": "That is Spiliada.", "ok": false}, {"t": "Exercising jurisdiction is contrary to its international and commercial character, or an abuse of its process", "why": "Correct.", "ok": true}, {"t": "The party in breach shows strong cause", "why": "That is the General Division's test for clauses.", "ok": false}, {"t": "The defendant has no assets in Singapore", "why": "Not a ground.", "ok": false}]}, "j5-bf8f592d": {"id": "j5-bf8f592d", "lesson": 5, "level": "J5 · TRANSFER", "q": "In a non-CCAA case, which test governs transfer from the General Division to the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>?", "hint": "More appropriate.", "opts": [{"t": "The <abbr title=\"Singapore International Commercial Court\">SICC</abbr> must be \"more appropriate\", with the action international and commercial and no prerogative relief sought (O 2 r 4(1))", "why": "Correct.", "ok": true}, {"t": "Strong cause", "why": "Not a transfer test.", "ok": false}, {"t": "Every party must consent", "why": "That is the extra <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> requirement (O 2 r 4(4)).", "ok": false}, {"t": "The claimant's choice alone", "why": "The court decides.", "ok": false}]}, "j5-c12ad068": {"id": "j5-c12ad068", "lesson": 5, "level": "J5 · TRANSFER", "q": "Why does O 2 r 4(4) require every party's consent to transfer in a <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> case?", "hint": "Art 8(5).", "opts": [{"t": "Because the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> bans transfers", "why": "It requires the parties' choice to be taken into account (s 11(5)).", "ok": false}, {"t": "Because the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> cannot hear <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> cases otherwise", "why": "A post-2016 High Court clause includes the <abbr title=\"Singapore International Commercial Court\">SICC</abbr>.", "ok": false}, {"t": "To protect recognition abroad: art 8(5) <abbr title=\"Hague Convention on Choice of Court Agreements 2005\">HCCCA</abbr> lets a foreign court refuse recognition against a party that objected in time to a discretionary transfer", "why": "Correct (<abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>).", "ok": true}, {"t": "To speed up proceedings", "why": "The point is enforceability.", "ok": false}]}, "j5-4c20339f": {"id": "j5-4c20339f", "lesson": 5, "level": "J5 · JOINDER", "q": "Third party C, not party to the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> clause, is joined and seeks a stay. Can the <abbr title=\"Singapore International Commercial Court\">SICC</abbr> weigh C's connections with Thailand?", "hint": "Who agreed in writing?", "opts": [{"t": "No: joined parties cannot seek a stay", "why": "C may rely on O 2 r 3(2).", "ok": false}, {"t": "Yes: the O 2 r 3(3) bar on considering foreign connections protects only parties to a written jurisdiction agreement", "why": "Correct.", "ok": true}, {"t": "Only under Spiliada", "why": "The <abbr title=\"Singapore International Commercial Court\">SICC</abbr> applies O 2 r 3.", "ok": false}, {"t": "No: O 2 r 3(3) applies to everyone", "why": "It protects only those who agreed in writing.", "ok": false}]}, "j5-d94db12f": {"id": "j5-d94db12f", "lesson": 5, "level": "J5 · JOINDER", "q": "Does C need to have signed a written jurisdiction agreement to be joined?", "hint": "Coercive joinder.", "opts": [{"t": "Only for counterclaims", "why": "The rule covers joinder generally.", "ok": false}, {"t": "Yes, always", "why": "Coercive joinder of non-signatories is the key advantage over arbitration.", "ok": false}, {"t": "No, unless C is a State or sovereign (O 10 r 5(2))", "why": "Correct.", "ok": true}, {"t": "Only if C is abroad", "why": "Location affects service, not this requirement.", "ok": false}]}, "j6-172d12d1": {"id": "j6-172d12d1", "lesson": 6, "level": "J6 · BASICS", "q": "An <abbr title=\"Anti-suit injunction\">ASI</abbr> is addressed to whom?", "hint": "In personam.", "opts": [{"t": "The respondent party, in personam; breach is contempt", "why": "Correct; it only indirectly affects the foreign court.", "ok": true}, {"t": "The foreign court", "why": "A Singapore court cannot order a foreign court.", "ok": false}, {"t": "The foreign government", "why": "Not at all.", "ok": false}, {"t": "Both parties equally", "why": "It restrains the respondent.", "ok": false}]}, "j6-a15249c5": {"id": "j6-a15249c5", "lesson": 6, "level": "J6 · AMENABILITY", "q": "Is amenability required for a contractual <abbr title=\"Anti-suit injunction\">ASI</abbr>?", "hint": "Always.", "opts": [{"t": "No: breach of the clause is enough", "why": "Breach replaces natural forum and vexation, not amenability.", "ok": false}, {"t": "Only for vexation ASIs", "why": "It applies to all three bases.", "ok": false}, {"t": "Only if the respondent is a company", "why": "Status is irrelevant.", "ok": false}, {"t": "Yes: it is always required, whatever the basis (Cooperative Muratori)", "why": "Correct.", "ok": true}]}, "j6-7eb370ca": {"id": "j6-7eb370ca", "lesson": 6, "level": "J6 · INTEREST", "q": "The applicant shows only that Singapore is the natural forum. Is that enough for a vexation <abbr title=\"Anti-suit injunction\">ASI</abbr>?", "hint": "Something more.", "opts": [{"t": "Yes, natural forum is the whole test", "why": "That would let Singapore impose its own natural-forum view on foreign courts.", "ok": false}, {"t": "No, because natural forum is irrelevant to ASIs", "why": "It is relevant to sufficient interest.", "ok": false}, {"t": "No: natural forum alone never justifies an <abbr title=\"Anti-suit injunction\">ASI</abbr>; there must be vexation or prejudice too (SNIA)", "why": "Correct.", "ok": true}, {"t": "Yes, if the foreign court refused a stay", "why": "That refusal is no bar, but it does not make natural forum enough.", "ok": false}]}, "j6-0ea2103c": {"id": "j6-0ea2103c", "lesson": 6, "level": "J6 · INTEREST", "q": "The respondent sued in Court A; the natural forum is Court B; Singapore has no connection. Should Singapore grant an <abbr title=\"Anti-suit injunction\">ASI</abbr>?", "hint": "Dual fora.", "opts": [{"t": "Yes, under s 4(10A) <abbr title=\"Civil Law Act 1909\">CLA</abbr> automatically", "why": "It gives power, not discretion.", "ok": false}, {"t": "Yes, if the respondent is amenable", "why": "Amenability is necessary, not sufficient.", "ok": false}, {"t": "Yes, because Court B cannot restrain the respondent", "why": "Airbus rejected that: only an interested jurisdiction can act.", "ok": false}, {"t": "Generally no: comity requires sufficient interest, and Singapore should not be an \"international busybody\" (Airbus; Akai)", "why": "Correct, save extreme cases.", "ok": true}]}, "j6-2e7179a4": {"id": "j6-2e7179a4", "lesson": 6, "level": "J6 · CONTRACT", "q": "A choice of law clause picks Singapore law. The respondent sues in California, which may apply its own law. Is that a breach founding an <abbr title=\"Anti-suit injunction\">ASI</abbr>?", "hint": "Declaratory.", "opts": [{"t": "Yes, if Singapore is the natural forum", "why": "That is a vexation point, not breach.", "ok": false}, {"t": "Only under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> concerns choice of court agreements.", "ok": false}, {"t": "Yes, suing where the chosen law will not apply always breaches", "why": "That is Briggs's argument, considered but not adopted.", "ok": false}, {"t": "Ordinarily no: a choice of law clause is declaratory, not promissory (Ace Insurance)", "why": "Correct; \"very clear language\" is needed.", "ok": true}]}, "j6-0b2f4182": {"id": "j6-0b2f4182", "lesson": 6, "level": "J6 · CONTRACT", "q": "The applicant waited until the foreign proceedings reached trial, having first contested jurisdiction there. Is the delay excused?", "hint": "Simultaneous.", "opts": [{"t": "Yes, delay never matters in contractual cases", "why": "Comity re-enters with delay.", "ok": false}, {"t": "Yes, it had to exhaust remedies abroad first", "why": "Sun Travels rejected this.", "ok": false}, {"t": "No: contesting jurisdiction abroad does not excuse delay; no \"two bites at the cherry\" (Sun Travels)", "why": "Correct; the foreign case's progress weighs heavily.", "ok": true}, {"t": "Only if the delay exceeded a year", "why": "Progress matters more than length.", "ok": false}]}, "j6-be16fe4a": {"id": "j6-be16fe4a", "lesson": 6, "level": "J6 · ABUSE", "q": "After a Singapore judgment on a trust issue, the respondent sues in California on judicial estoppel, which raises the same issue under a new label. Can Singapore restrain it?", "hint": "Different sides of the same coin.", "opts": [{"t": "No: abuse requires Singapore to be the natural forum", "why": "Natural forum is irrelevant for consecutive abuse.", "ok": false}, {"t": "Only if California has refused a stay", "why": "Not required.", "ok": false}, {"t": "Yes: protecting the Singapore judgment is a self-evident interest, and a new label does not matter (BCS v Baker)", "why": "Correct.", "ok": true}, {"t": "No: judicial estoppel cannot be brought in Singapore, so it is a new claim", "why": "That it could not be brought here is irrelevant.", "ok": false}]}, "j6-c0dcfe34": {"id": "j6-c0dcfe34", "lesson": 6, "level": "J6 · VEXATION", "q": "Which alone is NOT enough to make foreign proceedings vexatious?", "hint": "Duplication alone.", "opts": [{"t": "Relitigating a decided issue under a new label", "why": "That is vexatious and an abuse (BCS v Baker).", "ok": false}, {"t": "A key witness who cannot be compelled abroad", "why": "That can be vexatious (UBS v Telesto).", "ok": false}, {"t": "Losing a contribution claim available only in Singapore", "why": "That was vexatious in SNIA.", "ok": false}, {"t": "Parallel proceedings with a risk of conflicting judgments", "why": "Correct (UBS v Telesto); \"something more\" is needed.", "ok": true}]}, "j6-2e8d5ece": {"id": "j6-2e8d5ece", "lesson": 6, "level": "J6 · BASES", "q": "Which elements make up a contractual <abbr title=\"Anti-suit injunction\">ASI</abbr>, per Cooperative Muratori?", "hint": "Three elements.", "opts": [{"t": "Amenability, breach of the clause, and no strong reasons from the respondent", "why": "Correct; natural forum and injustice drop out.", "ok": true}, {"t": "Natural forum and breach", "why": "Natural forum does not arise in a contractual <abbr title=\"Anti-suit injunction\">ASI</abbr>.", "ok": false}, {"t": "Amenability, natural forum, vexation and no undue injustice", "why": "That is the vexation <abbr title=\"Anti-suit injunction\">ASI</abbr> (Kirkham).", "ok": false}, {"t": "Only breach of the clause", "why": "Amenability is always required.", "ok": false}]}, "j6-bd1ee1c5": {"id": "j6-bd1ee1c5", "lesson": 6, "level": "J6 · BASES", "q": "Why must the applicant name its basis?", "hint": "Different elements.", "opts": [{"t": "Because the foreign court requires it", "why": "Singapore law governs the <abbr title=\"Anti-suit injunction\">ASI</abbr>.", "ok": false}, {"t": "Because the elements differ between contractual, vexation and abuse of process ASIs (Cooperative Muratori)", "why": "Correct; the Kirkham factors are no box-ticking statute.", "ok": true}, {"t": "Because the burden is always on the respondent", "why": "The applicant bears the burden overall.", "ok": false}, {"t": "Because only one basis can ever succeed", "why": "Several strands may operate, but they are conceptually distinct.", "ok": false}]}, "j6-21c9cb53": {"id": "j6-21c9cb53", "lesson": 6, "level": "J6 · INTEREST", "q": "The clause is an <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr> for Hong Kong; the respondent sues in Thailand; the applicant asks Singapore for an <abbr title=\"Anti-suit injunction\">ASI</abbr>. What is the general approach?", "hint": "Chosen court.", "opts": [{"t": "Only the Thai court can decide", "why": "The issue is whether Singapore should act.", "ok": false}, {"t": "Go to the chosen court (Hong Kong); Singapore generally declines (Akai)", "why": "Correct; per Chong, Akai's force may be weaker today.", "ok": true}, {"t": "Singapore always grants it to uphold any <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr>", "why": "Not for a foreign <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr>.", "ok": false}, {"t": "Singapore grants it if the applicant has Singapore assets", "why": "Akai: enforcement against assets is \"an entirely different matter\".", "ok": false}]}, "j6-2c824b2b": {"id": "j6-2c824b2b", "lesson": 6, "level": "J6 · CONTRACT", "q": "Under a multi-tiered \"shall first negotiate, then mediate\" clause, the respondent sues abroad first. What <abbr title=\"Anti-suit injunction\">ASI</abbr> may issue, per Finaport?", "hint": "Until the tiers are done.", "opts": [{"t": "An <abbr title=\"Anti-suit injunction\">ASI</abbr> only if mediation would succeed", "why": "Impracticality is no answer.", "ok": false}, {"t": "An <abbr title=\"Anti-suit injunction\">ASI</abbr> restraining the suit until the preconditions are met, with liberty to apply", "why": "Correct; suing is not a per se breach of the clause.", "ok": true}, {"t": "None: tiered clauses are unenforceable", "why": "Finaport found no principled distinction from EJCs.", "ok": false}, {"t": "A permanent <abbr title=\"Anti-suit injunction\">ASI</abbr> barring the suit forever", "why": "The restraint lasts until the tiers are completed.", "ok": false}]}, "j6-41af7878": {"id": "j6-41af7878", "lesson": 6, "level": "J6 · ABUSE", "q": "In BCS v Baker, how do you tell concurrent from consecutive proceedings?", "hint": "The specific claim.", "opts": [{"t": "By when the specific claim to be enjoined was raised abroad, not when the actions began", "why": "Correct; <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>'s footnote states it the other way.", "ok": true}, {"t": "By which action began first", "why": "That is the approach the judgment rejects.", "ok": false}, {"t": "By whether the foreign court has given judgment", "why": "That is the <abbr title=\"Anti-enforcement injunction\">AEI</abbr> question.", "ok": false}, {"t": "By the governing law", "why": "Irrelevant.", "ok": false}]}, "j6-66cade9e": {"id": "j6-66cade9e", "lesson": 6, "level": "J6 · INJUSTICE", "q": "For which basis does the \"no undue injustice to the respondent\" limb apply?", "hint": "Kirkham's coin.", "opts": [{"t": "Vexation ASIs only", "why": "Correct; for abuse the advantage is irrelevant, and for contract it goes to strong reasons.", "ok": true}, {"t": "All three bases", "why": "Not for abuse or contract.", "ok": false}, {"t": "Contractual ASIs only", "why": "The respondent's points go to strong reasons there.", "ok": false}, {"t": "Abuse of process ASIs only", "why": "The foreign advantage is no answer there.", "ok": false}]}, "j6-77d9e5d7": {"id": "j6-77d9e5d7", "lesson": 6, "level": "J6 · THIRD PARTIES", "q": "A sues C (a non-party) abroad, and B (A's counterparty under a Singapore <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr>) seeks the <abbr title=\"Anti-suit injunction\">ASI</abbr>. Which route works, per Asiana?", "hint": "Bypass.", "opts": [{"t": "Rely on <abbr title=\"Contracts (Rights of Third Parties) Act 2001\">CRTPA</abbr> s 2(1)(b)", "why": "That was rejected in VKC v VJZ for C, and B is not a third party anyway.", "ok": false}, {"t": "Nothing: B can never act", "why": "Asiana allows two routes.", "ok": false}, {"t": "Show B has an interest in C, e.g. it must indemnify C", "why": "Asiana rejected that as over-inclusive.", "ok": false}, {"t": "Show the suit against C is really a bypass of the clause, making it vexatious as between A and B", "why": "Correct; or show the clause clearly covers claims against C.", "ok": true}]}, "j6-f4e0546a": {"id": "j6-f4e0546a", "lesson": 6, "level": "J6 · HCCCA", "q": "Should a non-chosen court ever grant an <abbr title=\"Anti-suit injunction\">ASI</abbr> against proceedings in the chosen court of a <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> clause?", "hint": "Against the chosen court.", "opts": [{"t": "Only after judgment", "why": "Then it would be an <abbr title=\"Anti-enforcement injunction\">AEI</abbr>, and still unsupportable.", "ok": false}, {"t": "Yes, under s 10 <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "s 10 leaves interim measures outside the Act; it does not authorise undermining the chosen court.", "ok": false}, {"t": "Yes, if the non-chosen court is the natural forum", "why": "Natural forum cannot trump the agreement here.", "ok": false}, {"t": "Never: it never supports the agreement (<abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>)", "why": "Correct.", "ok": true}]}, "j7-9dd0e30e": {"id": "j7-9dd0e30e", "lesson": 7, "level": "J7 · REQUIREMENTS", "q": "A Hong Kong judgment merely declares a Korean judgment enforceable in Hong Kong. Can the creditor sue on the Hong Kong judgment in Singapore?", "hint": "Launder.", "opts": [{"t": "Only under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> covers judgments of a chosen court.", "ok": false}, {"t": "No: a judgment on a judgment is not on the merits and is unenforceable at common law (Sang Cheol Woo)", "why": "Correct; enforce the Korean judgment directly.", "ok": true}, {"t": "Yes, under Desert Palace", "why": "<abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr> says Desert Palace did not grapple with the theory.", "ok": false}, {"t": "Yes, any final money judgment counts", "why": "It never examined the issues.", "ok": false}]}, "j7-8b43fa76": {"id": "j7-8b43fa76", "lesson": 7, "level": "J7 · JURISDICTION", "q": "The foreign court took jurisdiction by serving the debtor out of its territory under its own rules. Does that give it international jurisdiction for Singapore?", "hint": "Closed categories.", "opts": [{"t": "Only if there is a real and substantial connection", "why": "That Canadian ground is not adopted.", "ok": false}, {"t": "Yes, Singapore has its own service-out rules, so it must accept others'", "why": "There is no mirror image.", "ok": false}, {"t": "Yes, if the foreign court found it had jurisdiction", "why": "That finding creates no estoppel here.", "ok": false}, {"t": "No: Singapore tests international jurisdiction by its own narrower conflict rules (presence or submission), with no mirror image", "why": "Correct.", "ok": true}]}, "j7-7044bdf0": {"id": "j7-7044bdf0", "lesson": 7, "level": "J7 · SUBMISSION", "q": "The debtor applied abroad to set aside service on forum non conveniens grounds and lost. Did it submit?", "hint": "Henry v IGCF.", "opts": [{"t": "Arguably not: IGCF (PC) rejected Henry v Geoprosco as \"unrealistic and irrational\", and <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr> treats any failed set-aside as a protest", "why": "Correct, though Henry said otherwise (argue both).", "ok": true}, {"t": "No, because it lost", "why": "Losing is not what matters; the nature of the step is.", "ok": false}, {"t": "Yes, definitely: Henry v Geoprosco is binding in Singapore", "why": "Nimbus assumed Henry without deciding; IGCF points the other way.", "ok": false}, {"t": "Yes, any appearance abroad is submission", "why": "Protest appearances are not.", "ok": false}]}, "j7-148f5433": {"id": "j7-148f5433", "lesson": 7, "level": "J7 · PRESENCE", "q": "A company's sales representative stayed at a hotel in country X for a few days taking orders. Was the company present in X?", "hint": "Fixed place.", "opts": [{"t": "Yes, if X's court served him", "why": "Service does not create presence of the company.", "ok": false}, {"t": "No: no fixed place of business (Littauer Glove)", "why": "Correct.", "ok": true}, {"t": "Yes, if the contracts were made in X", "why": "Place of contracting is not the presence test.", "ok": false}, {"t": "Yes, any business activity counts", "why": "Adams v Cape needs a fixed place for more than a minimal period.", "ok": false}]}, "j7-f4c4c2d0": {"id": "j7-f4c4c2d0", "lesson": 7, "level": "J7 · FRAUD", "q": "The debtor alleges the creditor's witnesses lied at the foreign trial, which the debtor attended. It has no fresh evidence. Does the fraud defence succeed?", "hint": "Could it challenge it there?", "opts": [{"t": "Yes: fraud always unravels everything", "why": "Abouloff applies only to extrinsic fraud.", "ok": false}, {"t": "Yes: Singapore will retry the facts", "why": "Singapore does not review the merits.", "ok": false}, {"t": "Only if the foreign court is corrupt", "why": "That would be a different, extrinsic case.", "ok": false}, {"t": "No: this is intrinsic fraud, needing fresh evidence not discoverable with reasonable diligence (Hong Pian Tee)", "why": "Correct.", "ok": true}]}, "j7-e5591fe2": {"id": "j7-e5591fe2", "lesson": 7, "level": "J7 · PUBLIC POLICY", "q": "A Macau casino obtains a judgment for gambling debts and sues on it in Singapore. Per Venetian Macau…", "hint": "Statutory policy.", "opts": [{"t": "Burswood binds and the judgment is enforced", "why": "Venetian Macau confined Burswood to the repealed <abbr title=\"Reciprocal Enforcement of Commonwealth Judgments Act (repealed)\">RECJA</abbr>.", "ok": false}, {"t": "Gambling is not a public policy matter in Singapore", "why": "Gambling save as regulated is contrary to Singapore policy.", "ok": false}, {"t": "the judgment is enforced because only the judgment's effect matters", "why": "The statute draws no distinction between direct claims and actions on judgments.", "ok": false}, {"t": "enforcement is contrary to public policy, because s 5(2) <abbr title=\"Civil Law Act 1909\">CLA</abbr> is statutory policy and prevails", "why": "Correct; Burswood turned on <abbr title=\"Reciprocal Enforcement of Commonwealth Judgments Act (repealed)\">RECJA</abbr>'s cause-of-action test.", "ok": true}]}, "j7-6847761c": {"id": "j7-6847761c", "lesson": 7, "level": "J7 · PENAL", "q": "A foreign court orders the debtor to pay 20% statutory interest to the private creditor. Is that penal?", "hint": "Who gets the money?", "opts": [{"t": "Yes: 20% is excessive", "why": "Size alone is not the test.", "ok": false}, {"t": "Only if the creditor is a State entity", "why": "Here it is private.", "ok": false}, {"t": "No: penal means payable to the State; this is payable to a private creditor (Sang Cheol Woo)", "why": "Correct.", "ok": true}, {"t": "Yes: any statutory sum is penal", "why": "The test looks at who recovers and why.", "ok": false}]}, "j7-f2af3da5": {"id": "j7-f2af3da5", "lesson": 7, "level": "J7 · LIMITATION", "q": "How long does a creditor have to sue on a foreign judgment at common law?", "hint": "Implied debt.", "opts": [{"t": "No limit", "why": "That is the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> position (no implied debt is sued on).", "ok": false}, {"t": "Six years under s 6(1)(a) Limitation Act, from when it became final under foreign law", "why": "Correct (Poh Soon Kiat; Sang Cheol Woo).", "ok": true}, {"t": "Whatever the foreign law says", "why": "Singapore's Limitation Act applies to the implied debt.", "ok": false}, {"t": "Twelve years, as for Singapore judgments", "why": "s 6(3) covers only Singapore judgments.", "ok": false}]}, "j7-86681e38": {"id": "j7-86681e38", "lesson": 7, "level": "J7 · REGIME", "q": "The foreign court was the chosen court under an exclusive clause in a Hague Contracting State, after entry into force. Which regime?", "hint": "Chosen court.", "opts": [{"t": "None: chosen-court judgments enforce themselves", "why": "An application is needed.", "ok": false}, {"t": "<abbr title=\"Reciprocal Enforcement of Foreign Judgments Act 1959 (not examinable)\">REFJA</abbr>, if the country is gazetted", "why": "<abbr title=\"Reciprocal Enforcement of Foreign Judgments Act 1959 (not examinable)\">REFJA</abbr> s 2A: the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> ousts it.", "ok": false}, {"t": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, which ousts <abbr title=\"Reciprocal Enforcement of Foreign Judgments Act 1959 (not examinable)\">REFJA</abbr> but leaves the common law open (s 21)", "why": "Correct.", "ok": true}, {"t": "Common law only", "why": "The <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> applies, though the common law remains available.", "ok": false}]}, "j7-09912134": {"id": "j7-09912134", "lesson": 7, "level": "J7 · REQUIREMENTS", "q": "Which is NOT a common law requirement for recognition (as opposed to enforcement)?", "hint": "Shield, not sword.", "opts": [{"t": "International jurisdiction of the foreign court", "why": "Required.", "ok": false}, {"t": "A judgment on the merits", "why": "Required.", "ok": false}, {"t": "Final and conclusive", "why": "Required.", "ok": false}, {"t": "A money judgment for a definite sum", "why": "Correct: recognition has no money requirement.", "ok": true}]}, "j7-b1c1e877": {"id": "j7-b1c1e877", "lesson": 7, "level": "J7 · REQUIREMENTS", "q": "How is \"final and conclusive\" tested?", "hint": "Foreign law.", "opts": [{"t": "By whether an appeal is pending, always fatal", "why": "A pending appeal does not as such defeat finality.", "ok": false}, {"t": "By the creditor's say-so", "why": "It must be proved.", "ok": false}, {"t": "By Singapore law", "why": "The foreign court's own law decides finality.", "ok": false}, {"t": "By the foreign law, proved by expert evidence (Humpuss; Carl Zeiss)", "why": "Correct.", "ok": true}]}, "j7-3280e13a": {"id": "j7-3280e13a", "lesson": 7, "level": "J7 · DEFENCES", "q": "Can the debtor argue that the foreign court got the facts wrong?", "hint": "No appeal.", "opts": [{"t": "No: Singapore does not review the merits (Godard v Gray; Ralli v Angullia)", "why": "Correct; only a patent error of Singapore law is arguable (Merck, open).", "ok": true}, {"t": "Yes, under natural justice", "why": "Natural justice concerns notice and hearing.", "ok": false}, {"t": "Yes, if Singapore law would have decided differently", "why": "Still no review.", "ok": false}, {"t": "Yes, if the error is big enough", "why": "Size is not the test.", "ok": false}]}, "j7-56700527": {"id": "j7-56700527", "lesson": 7, "level": "J7 · RES JUDICATA", "q": "Mexican insolvency rulings under Mexican law are relied on to bind a party on a Singapore-law claim. Per Gonzalo Gil White…", "hint": "Same issue, same law?", "opts": [{"t": "there is no identity of issue, because the issues arose under different laws", "why": "Correct; look at identity of issues, not consequences.", "ok": true}, {"t": "the ruling binds because it is final", "why": "Finality is only one requirement.", "ok": false}, {"t": "Singapore must apply Mexican law", "why": "Not the point.", "ok": false}, {"t": "issue estoppel binds because the parties are the same", "why": "Identity of issue is also needed.", "ok": false}]}, "j7-465a48f7": {"id": "j7-465a48f7", "lesson": 7, "level": "J7 · RES JUDICATA", "q": "A foreign court found the debtor submitted to its jurisdiction. Does that finding bind Singapore?", "hint": "Decides for itself.", "opts": [{"t": "Yes, by issue estoppel", "why": "Singapore decides this itself.", "ok": false}, {"t": "Yes, under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr> always", "why": "Under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, findings of fact on jurisdiction bind (s 13(3)(b)), but that is the statute, not the common law.", "ok": false}, {"t": "Only if the debtor appealed", "why": "Not the test.", "ok": false}, {"t": "No: international jurisdiction is an issue Singapore decides for itself; otherwise it would \"sub-contract\" the question (Desert Sun)", "why": "Correct.", "ok": true}]}, "j7-91bb1503": {"id": "j7-91bb1503", "lesson": 7, "level": "J7 · CCAA", "q": "Under the <abbr title=\"Choice of Court Agreements Act 2016 (Singapore&#x27;s statute giving effect to the HCCCA)\">CCAA</abbr>, which ground is MANDATORY?", "hint": "s 14.", "opts": [{"t": "Excess damages", "why": "Discretionary (s 16).", "ok": false}, {"t": "An inconsistent earlier foreign judgment", "why": "Discretionary (s 15(1)(e)).", "ok": false}, {"t": "Procedural fraud (s 14(b))", "why": "Correct; s 14 also covers no timely notice and manifest public policy.", "ok": true}, {"t": "The clause is void under the foreign law", "why": "Discretionary (s 15(1)(a)).", "ok": false}]}, "j7-fda9e2a0": {"id": "j7-fda9e2a0", "lesson": 7, "level": "J7 · AEI", "q": "The creditor obtained the foreign judgment in breach of an <abbr title=\"Exclusive jurisdiction clause\">EJC</abbr>. Is that alone enough for an <abbr title=\"Anti-enforcement injunction\">AEI</abbr>, per Sun Travels?", "hint": "Exceptional.", "opts": [{"t": "Yes, party autonomy is a separate basis", "why": "Sun Travels rejected that.", "ok": false}, {"t": "No: breach or vexation alone is not enough; exceptional circumstances tied to unconscionability are needed", "why": "Correct.", "ok": true}, {"t": "Yes, breach of a clause always justifies restraint", "why": "That suffices for an <abbr title=\"Anti-suit injunction\">ASI</abbr>, not an <abbr title=\"Anti-enforcement injunction\">AEI</abbr>.", "ok": false}, {"t": "Only if the debtor applied within a year", "why": "Mere passage of time is not the test.", "ok": false}]}, "c1-8d0ab09b": {"id": "c1-8d0ab09b", "lesson": 8, "level": "C1 · CHARACTERISATION", "q": "In Macmillan, the claim was framed as restitution, but what did the court characterise?", "hint": "Issue, not cause of action.", "opts": [{"t": "The contract under which the shares were pledged", "why": "The issue was title and priority.", "ok": false}, {"t": "Procedure, so Singapore law", "why": "Not procedure.", "ok": false}, {"t": "The cause of action, restitution", "why": "That is exactly the approach rejected.", "ok": false}, {"t": "The true issue, priority over the shares, governed by the lex situs", "why": "Correct: look beyond the formulation of the claim.", "ok": true}]}, "c1-9c93fae1": {"id": "c1-9c93fae1", "lesson": 8, "level": "C1 · CHARACTERISATION", "q": "Which law characterises the issue?", "hint": "Enlightened lex fori.", "opts": [{"t": "Whichever law the claimant pleads", "why": "The claimant's framing cannot steer the governing law.", "ok": false}, {"t": "The lex causae", "why": "Circular: it is found only after characterising.", "ok": false}, {"t": "International law", "why": "Characterisation is by the forum.", "ok": false}, {"t": "The lex fori, in an enlightened, internationalist way", "why": "Correct (Shahdadpuri; Raiffeisen; Macmillan).", "ok": true}]}, "c1-3677eecb": {"id": "c1-3677eecb", "lesson": 8, "level": "C1 · CHARACTERISATION", "q": "A breach of confidence claim arises from an employment contract governed by German law. How is it characterised, per Rickshaw?", "hint": "Nature and origins.", "opts": [{"t": "As an equitable claim governed by Singapore law", "why": "That is the rejected lex fori approach.", "ok": false}, {"t": "As a tort, under double actionability", "why": "Not on Rickshaw's facts.", "ok": false}, {"t": "As procedure", "why": "Not procedure.", "ok": false}, {"t": "By its legal foundation, so as contractual, applying the contract's German law", "why": "Correct; Rickshaw rejected the Australian lex fori approach.", "ok": true}]}, "c1-7431a860": {"id": "c1-7431a860", "lesson": 8, "level": "C1 · GAP", "q": "A forum rule is substantive and the lex causae's equivalent rule is procedural. What happens?", "hint": "Neither applies.", "opts": [{"t": "Only the foreign rule applies", "why": "It is procedural, so the forum would not apply it.", "ok": false}, {"t": "Cumulation: both apply", "why": "That is the reverse combination.", "ok": false}, {"t": "A gap: neither applies, so a party urges re-characterising in a broad internationalist spirit", "why": "Correct.", "ok": true}, {"t": "Only the forum rule applies", "why": "It is substantive, so it yields to the lex causae.", "ok": false}]}, "c1-f4194e4c": {"id": "c1-f4194e4c", "lesson": 8, "level": "C1 · PROCEDURE", "q": "A foreign statute says \"no action shall be brought\" on gambling debts. Under Star City, how is it characterised?", "hint": "Existence v enforcement.", "opts": [{"t": "Substantive: it destroys the right", "why": "That would be \"no obligation exists\".", "ok": false}, {"t": "Procedural: it bars enforcement, so Singapore law (the lex fori) governs the point", "why": "Correct; contrast a rule that no obligation exists.", "ok": true}, {"t": "Neither: it is public policy", "why": "Public policy is a separate overlay.", "ok": false}, {"t": "Always substantive under the functional approach", "why": "The functional approach is left open, and argued only in the alternative.", "ok": false}]}, "c1-3ccdee0f": {"id": "c1-3ccdee0f", "lesson": 8, "level": "C1 · DAMAGES", "q": "Under the traditional split, which part of damages is procedural?", "hint": "Heads v quantum.", "opts": [{"t": "The heads of damage", "why": "Heads are substantive.", "ok": false}, {"t": "Remoteness", "why": "Remoteness is substantive (D'Almeida Araujo).", "ok": false}, {"t": "Quantum, so the Singapore amount applies", "why": "Correct; heads are substantive.", "ok": true}, {"t": "None of it", "why": "Quantum is traditionally procedural.", "ok": false}]}, "c1-49f5b17f": {"id": "c1-49f5b17f", "lesson": 8, "level": "C1 · REMEDIES", "q": "Per Rappo, why was a constructive trust unavailable even though the case was heard in Singapore?", "hint": "Remedy follows right.", "opts": [{"t": "Swiss law governed the relationship, and remedies are \"a function of the law that governs the relevant relationship\"", "why": "Correct.", "ok": true}, {"t": "Singapore does not recognise constructive trusts", "why": "It does; the governing law did not.", "ok": false}, {"t": "The claimant did not plead it", "why": "Not the reason given.", "ok": false}, {"t": "Remedies are always procedural", "why": "Rappo took the modern view.", "ok": false}]}, "c1-932d63bd": {"id": "c1-932d63bd", "lesson": 8, "level": "C1 · PROOF", "q": "Neither party pleads Ruritanian law, though the contract is governed by it. What law does the court apply?", "hint": "Not pleaded.", "opts": [{"t": "None: the claim fails", "why": "The default rule applies Singapore law.", "ok": false}, {"t": "Ruritanian law, presumed similar", "why": "The presumption applies only once foreign law is pleaded.", "ok": false}, {"t": "Ruritanian law, which the court must research itself", "why": "No judicial notice.", "ok": false}, {"t": "Singapore law, in its own right: no conflicts issue arises (Brownlie; EFT Holdings)", "why": "Correct.", "ok": true}]}, "c1-8ec563fa": {"id": "c1-8ec563fa", "lesson": 8, "level": "C1 · PROOF", "q": "The claimant pleads Indonesian law but fails to prove it. The issue is a technical statutory rule. Is the presumption of similarity likely to apply?", "hint": "Fair and reasonable?", "opts": [{"t": "Less likely: it is less apt for a statutory rule and a civil law system, so the claimant may simply lose", "why": "Correct, though the question is whether there is a materially similar rule.", "ok": true}, {"t": "Yes, because Indonesia is a common law system", "why": "Indonesia is a civil law system.", "ok": false}, {"t": "No, the court must apply Singapore law in its own right", "why": "That is the not-pleaded rule.", "ok": false}, {"t": "Yes, always", "why": "It applies only where fair and reasonable.", "ok": false}]}, "c1-22062251": {"id": "c1-22062251", "lesson": 8, "level": "C1 · LIMITATION", "q": "Under the <abbr title=\"Foreign Limitation Periods Act 2012\">FLPA</abbr>, which limitation law applies to a contract governed by Japanese law?", "hint": "Lex causae.", "opts": [{"t": "Whichever is longer", "why": "No such rule.", "ok": false}, {"t": "Both, cumulatively", "why": "That is the English position for tort.", "ok": false}, {"t": "Singapore's Limitation Act, as the lex fori", "why": "The <abbr title=\"Foreign Limitation Periods Act 2012\">FLPA</abbr> displaces the old procedural characterisation.", "ok": false}, {"t": "Japanese limitation law only, whether Japan calls it substantive or procedural (s 3(1), s 6(2))", "why": "Correct.", "ok": true}]}, "c1-768aef67": {"id": "c1-768aef67", "lesson": 8, "level": "C1 · STAGES", "q": "What are the three stages of choice of law, per Macmillan?", "hint": "Characterise, connect, apply.", "opts": [{"t": "Substance, procedure, public policy", "why": "Those are tools within the stages.", "ok": false}, {"t": "Plead, prove and apply foreign law", "why": "That is the proof of foreign law.", "ok": false}, {"t": "Characterise the issue, select the connecting factor, apply the law", "why": "Correct.", "ok": true}, {"t": "Jurisdiction, choice of law, enforcement", "why": "Those are the three questions of conflict of laws.", "ok": false}]}, "c1-51f3bae5": {"id": "c1-51f3bae5", "lesson": 8, "level": "C1 · CHARACTERISATION", "q": "Why does the lex fori, not the lex causae, characterise?", "hint": "Circularity.", "opts": [{"t": "Because the claimant chooses Singapore", "why": "Not the reason.", "ok": false}, {"t": "Because Singapore law is always better", "why": "Not the reason.", "ok": false}, {"t": "Using the possible leges causae would be circular, since they are found only after characterising, and invites cumulation and gap", "why": "Correct (Shahdadpuri).", "ok": true}, {"t": "Because foreign law is never relevant", "why": "It is applied at stage 3.", "ok": false}]}, "c1-5fe823db": {"id": "c1-5fe823db", "lesson": 8, "level": "C1 · PROCEDURE", "q": "What is the status of the functional approach to substance and procedure in Singapore?", "hint": "Left open.", "opts": [{"t": "Adopted by the Court of Appeal", "why": "It was left open.", "ok": false}, {"t": "Rejected outright", "why": "Not rejected.", "ok": false}, {"t": "Left open by Goh Suan Hee, so Star City still applies, with the functional view argued in the alternative (CIFG v Polimet)", "why": "Correct.", "ok": true}, {"t": "Applies only to tort", "why": "It is a general question.", "ok": false}]}, "c1-66e8f3ad": {"id": "c1-66e8f3ad", "lesson": 8, "level": "C1 · LIMITATION", "q": "When is a foreign limitation period disapplied under <abbr title=\"Foreign Limitation Periods Act 2012\">FLPA</abbr> s 4(2)?", "hint": "Undue hardship.", "opts": [{"t": "Never: s 4(2) is about laches", "why": "It is the undue hardship rule.", "ok": false}, {"t": "When it causes undue hardship, greater than the circumstances warrant, flowing from the period itself (Recovery Vehicle 1)", "why": "Correct.", "ok": true}, {"t": "Whenever the claimant was unaware of it", "why": "Awareness is one factor; knowingly buying time-barred debts defeats the plea.", "ok": false}, {"t": "Whenever it is shorter than Singapore's", "why": "Being shorter is not enough.", "ok": false}]}, "c1-0f48188f": {"id": "c1-0f48188f", "lesson": 8, "level": "C1 · MANDATORY", "q": "Per JIO Minerals, did the Misrepresentation Act apply to misrepresentations made in Indonesia under a UAE-law contract?", "hint": "Supplements remedies.", "opts": [{"t": "No: the Act supplements common law remedies and applies only if Singapore law governs the contract", "why": "Correct (the choice of law aspect of the presumption).", "ok": true}, {"t": "Yes: it is an overriding mandatory rule", "why": "It is not.", "ok": false}, {"t": "Yes, because the claim was heard in Singapore", "why": "The forum alone does not trigger it.", "ok": false}, {"t": "Only if the claimant was a consumer", "why": "That is <abbr title=\"Unfair Contract Terms Act 1977\">UCTA</abbr> s 27(2)(b).", "ok": false}]}, "c1-f2215679": {"id": "c1-f2215679", "lesson": 8, "level": "C1 · MANDATORY", "q": "How does <abbr title=\"Unfair Contract Terms Act 1977\">UCTA</abbr> s 27(2)'s \"wholly or mainly to evade\" test compare with the bona fides test for an express choice?", "hint": "Wider, and superimposed.", "opts": [{"t": "They are identical", "why": "They differ in breadth and effect.", "ok": false}, {"t": "s 27(2) strikes out the chosen law entirely", "why": "The chosen law survives subject to the Act.", "ok": false}, {"t": "It is narrower than \"sole purpose\"", "why": "The reverse.", "ok": false}, {"t": "It is wider than \"sole purpose\", and the chosen law survives subject to <abbr title=\"Unfair Contract Terms Act 1977\">UCTA</abbr> rather than being struck out", "why": "Correct (<a class=\"xref\" href=\"c1.html#t-C1-7\">C1.7</a>; <a class=\"xref\" href=\"c2.html#p-C2-2-2\">C2.2.2</a>).", "ok": true}]}, "c1-13f547fc": {"id": "c1-13f547fc", "lesson": 8, "level": "C1 · PUBLIC POLICY", "q": "Which is the best example of a contract contrary to Singapore's fundamental public policy?", "hint": "Fundamental, not domestic.", "opts": [{"t": "A contract procured by economic duress", "why": "That stays with the proper law (Dimskal).", "ok": false}, {"t": "A contract void under Singapore domestic law only", "why": "Fundamental policy is narrower than domestic policy.", "ok": false}, {"t": "A contract governed by a civil law system", "why": "Irrelevant.", "ok": false}, {"t": "A contract procured by extreme duress, such as a human-shield threat (Royal Boskalis)", "why": "Correct.", "ok": true}]}, "c1-89e4a5d0": {"id": "c1-89e4a5d0", "lesson": 8, "level": "C1 · RENVOI", "q": "Does renvoi apply to the proper law of a contract?", "hint": "Domestic law.", "opts": [{"t": "Yes, single renvoi", "why": "Excluded in contract.", "ok": false}, {"t": "Only for limitation", "why": "Excluded there too (<abbr title=\"Foreign Limitation Periods Act 2012\">FLPA</abbr>).", "ok": false}, {"t": "No: the proper law means its domestic law (Ong Ghee Soon; Amin Rasheed)", "why": "Correct.", "ok": true}, {"t": "Yes, total renvoi", "why": "Excluded in contract.", "ok": false}]}, "c2-2ecf0288": {"id": "c2-2ecf0288", "lesson": 9, "level": "C2 · EXPRESS", "q": "Per Peh Teck Quee, when does an express choice of law fail for lack of bona fides?", "hint": "Sole purpose.", "opts": [{"t": "Whenever it avoids a mandatory rule", "why": "That is <abbr title=\"Unfair Contract Terms Act 1977\">UCTA</abbr>'s \"wholly or mainly\" test, with a different effect.", "ok": false}, {"t": "Whenever the chosen law has no connection with the contract", "why": "No connection is needed (Amin Rasheed).", "ok": false}, {"t": "Only if evading another law was its sole purpose", "why": "Correct; the clause is then struck out completely.", "ok": true}, {"t": "Whenever one party did not read it", "why": "Intention is objective.", "ok": false}]}, "c2-abdf968d": {"id": "c2-abdf968d", "lesson": 9, "level": "C2 · EXPRESS", "q": "A clause says \"governed by the laws of Singapore/or PRC\". What follows, per Shanghai Turbo?", "hint": "Floating law = void.", "opts": [{"t": "The court infers an implied choice", "why": "Skip Stage 2 after a failed express choice.", "ok": false}, {"t": "The claimant chooses when it sues", "why": "That would be a race to sue.", "ok": false}, {"t": "It is a floating clause, void as \"meaningless\", so the court goes straight to the objective proper law", "why": "Correct.", "ok": true}, {"t": "Singapore law applies as the first-named law", "why": "There is no such rule.", "ok": false}]}, "c2-95acee13": {"id": "c2-95acee13", "lesson": 9, "level": "C2 · EXPRESS", "q": "A party alleges fraud in the sale contract and says the choice of law clause is therefore void. Per CIMB?", "hint": "Infection test.", "opts": [{"t": "The clause stands only if the fraud is disproved", "why": "The point is the clause applies meanwhile.", "ok": false}, {"t": "The clause is void because the contract is voidable", "why": "Separability prevents that.", "ok": false}, {"t": "The lex fori decides the fraud first", "why": "Material validity is for the proper law.", "ok": false}, {"t": "The clause applies \"as if the contract were valid\": a disputed fraud does not necessarily infect consent to the clause", "why": "Correct; otherwise a bare allegation would neutralise it.", "ok": true}]}, "c2-f9df9917": {"id": "c2-f9df9917", "lesson": 9, "level": "C2 · EXPRESS", "q": "Why should a party usually lead with bona fides rather than the \"legal\" or public policy limbs of Vita Food?", "hint": "Strongest attack.", "opts": [{"t": "Bona fides needs no evidence", "why": "It needs evidence of sole purpose.", "ok": false}, {"t": "The other limbs were abolished", "why": "They exist but are weak.", "ok": false}, {"t": "Bona fides is tested by the chosen law", "why": "All limbs are tested by the lex fori.", "ok": false}, {"t": "\"Legal\" has an unclear meaning and the public policy limb duplicates the general reservation (<abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>)", "why": "Correct.", "ok": true}]}, "c2-6615fc54": {"id": "c2-6615fc54", "lesson": 9, "level": "C2 · IMPLIED", "q": "Which factor usually carries the most weight at Stage 2?", "hint": "Heavy factor.", "opts": [{"t": "The place where the contract was signed", "why": "It matters little unless performance is also there.", "ok": false}, {"t": "The currency of payment", "why": "USD carries little weight.", "ok": false}, {"t": "A jurisdiction or arbitration clause for country Y", "why": "Correct (Pacific Recreation): the chosen forum is presumed to apply its own law.", "ok": true}, {"t": "The language of the contract", "why": "English carries little weight.", "ok": false}]}, "c2-26d2acb8": {"id": "c2-26d2acb8", "lesson": 9, "level": "C2 · FORMATION", "q": "Per Lew v Nargolwala, can the lex fori decide whether a contract was formed when the putative proper law is unclear?", "hint": "No residual role.", "opts": [{"t": "Yes, always", "why": "That is Briggs's test, also rejected.", "ok": false}, {"t": "No: applying the lex fori regardless of connection is \"illogical\" and defeats uniformity, so it has no role even residually", "why": "Correct; Chong and Teo critique this.", "ok": true}, {"t": "Yes, as a fallback", "why": "Lew rejected Yeo's fallback.", "ok": false}, {"t": "Only for battle of forms", "why": "Lew now bars the lex fori fallback there too.", "ok": false}]}, "c2-b7184a8b": {"id": "c2-b7184a8b", "lesson": 9, "level": "C2 · FORM", "q": "A contract fails a writing requirement of its proper law but meets the requirements of the place where it was made. Is it formally valid?", "hint": "Either law.", "opts": [{"t": "No: the proper law alone governs form", "why": "Form has alternative validating laws.", "ok": false}, {"t": "Yes: meeting either the proper law or the lex loci contractus suffices (AQCEL, adopting PT Jaya Putra)", "why": "Correct.", "ok": true}, {"t": "Only if the parties intended it", "why": "Parties rarely think about formalities, which is why the rule validates.", "ok": false}, {"t": "Only under the lex fori", "why": "The lex fori governs only procedural formalities like s 6 <abbr title=\"Civil Law Act 1909\">CLA</abbr>.", "ok": false}]}, "c2-e8028205": {"id": "c2-e8028205", "lesson": 9, "level": "C2 · CAPACITY", "q": "A Norwegian municipality made swaps under English law, but Norwegian statute barred such contracts. Per the Haugesund majority?", "hint": "Ability to exercise specific rights.", "opts": [{"t": "English law alone decides capacity", "why": "A corporation needs capacity under both laws.", "ok": false}, {"t": "It lacked capacity (the internationalist sense), so the contract was void under the English proper law, with recovery in unjust enrichment", "why": "Correct.", "ok": true}, {"t": "The contract was valid but unenforceable", "why": "The consequences were voidness and restitution.", "ok": false}, {"t": "It had capacity because Norwegian law has no ultra vires doctrine", "why": "That was Etherton LJ's dissenting view.", "ok": false}]}, "c2-188fbb69": {"id": "c2-188fbb69", "lesson": 9, "level": "C2 · ILLEGALITY", "q": "A contract's real object, intended at formation, is to smuggle goods into a friendly country in breach of its export ban. Which route?", "hint": "Intention v action.", "opts": [{"t": "(A) The proper law only", "why": "Foster applies whatever the proper law.", "ok": false}, {"t": "(C) Foster v Driscoll: intention to break a friendly state's law, whatever the proper law", "why": "Correct.", "ok": true}, {"t": "(E) Ralli Brothers", "why": "Ralli looks to required performance at the contractual place, not intention.", "ok": false}, {"t": "(D) Lemenda", "why": "Lemenda concerns foreign public policy, not written law.", "ok": false}]}, "c2-cae4eb35": {"id": "c2-cae4eb35", "lesson": 9, "level": "C2 · ILLEGALITY", "q": "After contracting, the place of performance bans the required delivery. Which route, and what is the effect?", "hint": "After formation, at the place of performance.", "opts": [{"t": "(B) Forum public policy", "why": "Not a fundamental-policy case.", "ok": false}, {"t": "Neither route applies", "why": "Ralli applies to supervening illegality at the contractual place.", "ok": false}, {"t": "(E) Ralli Brothers: unenforceable in so far as performance is unlawful at the contractual place", "why": "Correct (on the independent-rule reading, Esben).", "ok": true}, {"t": "(C) Foster: the later ban creates wicked intention", "why": "Foster needs intention at formation; a later ban does not suffice.", "ok": false}]}, "c2-aad25a15": {"id": "c2-aad25a15", "lesson": 9, "level": "C2 · ILLEGALITY", "q": "Is breach of a foreign government's purchasing directive enough under Lemenda?", "hint": "Double breach.", "opts": [{"t": "Yes, if Singapore law governs", "why": "Still needs a similar Singapore policy.", "ok": false}, {"t": "No: foreign policy alone is insufficient, and a purchasing directive is government policy, not public policy in law (Shaikh Faisal)", "why": "Correct.", "ok": true}, {"t": "Yes, any foreign policy breach suffices", "why": "A coinciding Singapore domestic policy is needed.", "ok": false}, {"t": "Only under Ralli", "why": "Ralli concerns written law.", "ok": false}]}, "c2-a46b75b7": {"id": "c2-a46b75b7", "lesson": 9, "level": "C2 · ILLEGALITY", "q": "A loan agreement fixes no place of repayment. Malaysian exchange control law would make repayment from Malaysia illegal, but repayment is demanded in Singapore. Per Peh Teck Quee?", "hint": "In so far as.", "opts": [{"t": "Ralli does not bite: performance demanded in Singapore is not unlawful, and Ralli bites only \"in so far as\" performance is unlawful", "why": "Correct.", "ok": true}, {"t": "The proper law is replaced by Malaysian law", "why": "The proper law is unaffected.", "ok": false}, {"t": "Ralli bars repayment wherever demanded", "why": "Only in so far as unlawful at the contractual place.", "ok": false}, {"t": "Foster bars it", "why": "There was no contemplated adventure to break Malaysian law.", "ok": false}]}, "c2-7262ca94": {"id": "c2-7262ca94", "lesson": 9, "level": "C2 · STAGES", "q": "In what order is the proper law found?", "hint": "EPL, IPL, <abbr title=\"Objective proper law (the law with the closest and most real connection)\">OPL</abbr>.", "opts": [{"t": "Implied, then express, then objective", "why": "Express choice first.", "ok": false}, {"t": "Express choice, then implied choice, then closest and most real connection", "why": "Correct (Pacific Recreation; Bonython).", "ok": true}, {"t": "Closest connection, then express, then implied", "why": "Express choice comes first.", "ok": false}, {"t": "Lex fori, then express choice", "why": "The lex fori is not a stage.", "ok": false}]}, "c2-44c9ffd5": {"id": "c2-44c9ffd5", "lesson": 9, "level": "C2 · EXPRESS", "q": "Does an express choice of law need a connection with the contract?", "hint": "Neutral law allowed.", "opts": [{"t": "Only for consumer contracts", "why": "Not a requirement at all.", "ok": false}, {"t": "Yes, under the Hague Principles", "why": "Art 2(4) Hague Principles also needs no connection.", "ok": false}, {"t": "No: parties may choose a neutral or developed law (Peh Teck Quee; Amin Rasheed)", "why": "Correct.", "ok": true}, {"t": "Yes, a substantial connection", "why": "Not required.", "ok": false}]}, "c2-77906012": {"id": "c2-77906012", "lesson": 9, "level": "C2 · EXPRESS", "q": "After an express choice fails as not bona fide, does the court look for an implied choice?", "hint": "Skip Stage 2.", "opts": [{"t": "No: it goes straight to the objective proper law, inferring a choice being \"artificial\"", "why": "Correct (Shanghai Turbo; The Iran Vojdan).", "ok": true}, {"t": "It enforces the clause anyway", "why": "It is struck out.", "ok": false}, {"t": "It applies the lex fori", "why": "Not the rule.", "ok": false}, {"t": "Yes, always", "why": "Skip Stage 2.", "ok": false}]}, "c2-be7a5194": {"id": "c2-be7a5194", "lesson": 9, "level": "C2 · OPL", "q": "Which is NOT a relevant factor for the objective proper law?", "hint": "Spiliada ≠ <abbr title=\"Objective proper law (the law with the closest and most real connection)\">OPL</abbr>.", "opts": [{"t": "The convenience of witnesses, unless connected with the contract", "why": "Correct (Chong): that is a Spiliada factor.", "ok": true}, {"t": "A related transaction under the same law", "why": "Relevant.", "ok": false}, {"t": "The currency of payment", "why": "Relevant, though light.", "ok": false}, {"t": "The place where both parties perform", "why": "Usually the strongest factor.", "ok": false}]}, "c2-5785bb34": {"id": "c2-5785bb34", "lesson": 9, "level": "C2 · FORMATION", "q": "What does \"double bootstraps\" mean?", "hint": "Clause first, then contract.", "opts": [{"t": "Applying the lex fori twice", "why": "The lex fori has no role per Lew.", "ok": false}, {"t": "The putative proper law first decides whether the choice of law clause was incorporated, then whether the contract was formed", "why": "Correct (Chong).", "ok": true}, {"t": "Running Stage 2 and Stage 3 together", "why": "That is the \"merge\" point.", "ok": false}, {"t": "Applying two laws cumulatively to formation", "why": "Not the meaning.", "ok": false}]}, "c2-4972b637": {"id": "c2-4972b637", "lesson": 9, "level": "C2 · FORM", "q": "How is s 6 <abbr title=\"Civil Law Act 1909\">CLA</abbr> (no action on a guarantee without signed writing) characterised under Leroux v Brown?", "hint": "No action.", "opts": [{"t": "A capacity rule", "why": "It is about writing.", "ok": false}, {"t": "Procedural, so it binds a foreign-law contract sued on in Singapore", "why": "Correct; per <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>, possibly substantive on a functional view.", "ok": true}, {"t": "Substantive form, governed by the proper law", "why": "That is the functional critique, not the current rule.", "ok": false}, {"t": "Irrelevant to foreign-law contracts", "why": "It binds every Singapore action.", "ok": false}]}, "c2-5a12e4af": {"id": "c2-5a12e4af", "lesson": 9, "level": "C2 · CAPACITY", "q": "What is <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>'s preferred rule for a natural person's capacity to contract?", "hint": "Objective.", "opts": [{"t": "The express proper law", "why": "A subjective choice could be imposed by the stronger party.", "ok": false}, {"t": "The lex loci contractus", "why": "Fortuitous and unidentifiable online.", "ok": false}, {"t": "The objective proper law, so the stronger party cannot impose a law giving the weaker party capacity", "why": "Correct.", "ok": true}, {"t": "The lex domicilii", "why": "Unfair to an unaware counterparty.", "ok": false}]}, "c2-32832b84": {"id": "c2-32832b84", "lesson": 9, "level": "C2 · ILLEGALITY", "q": "Per Magdeev, what distinguishes Ralli from Foster?", "hint": "Action v intention.", "opts": [{"t": "\"Ralli looks to action, Foster … to intention\"", "why": "Correct.", "ok": true}, {"t": "Ralli concerns public policy; Foster concerns written law", "why": "Both concern written law; Lemenda concerns policy.", "ok": false}, {"t": "Ralli applies only to Singapore-law contracts", "why": "Ralli applies whatever the proper law.", "ok": false}, {"t": "Foster needs the illegal act to be carried out", "why": "Intention suffices, even if never carried out.", "ok": false}]}, "c3-ef9375ba": {"id": "c3-ef9375ba", "lesson": 10, "level": "C3 · RULE", "q": "Who must plead and prove that the conduct is not actionable under the foreign law?", "hint": "Limb (b) protects the defendant.", "opts": [{"t": "The court, of its own motion", "why": "Foreign law must be pleaded and proved.", "ok": false}, {"t": "The claimant, for both limbs", "why": "The claimant proves only limb (a), unless it invokes the exception to apply foreign law.", "ok": false}, {"t": "The defendant, since limb (b) exists for its benefit (EFT Holdings)", "why": "Correct; this makes the lex fori the dominant limb.", "ok": true}, {"t": "Nobody: foreign law is presumed to impose liability", "why": "The default rule applies Singapore law if it is not pleaded.", "ok": false}]}, "c3-6029dfe5": {"id": "c3-6029dfe5", "lesson": 10, "level": "C3 · RULE", "q": "Without displacement, what can the claimant recover under double actionability?", "hint": "Both rulebooks.", "opts": [{"t": "Whatever either law allows", "why": "Both limbs must be met.", "ok": false}, {"t": "Only what the foreign law allows", "why": "Singapore law can cut it down too.", "ok": false}, {"t": "Only what Singapore law allows", "why": "The foreign law can cut it down.", "ok": false}, {"t": "Only what both laws allow: the common denominator (McElroy v McAllister: only funeral expenses)", "why": "Correct.", "ok": true}]}, "c3-83c7dfa2": {"id": "c3-83c7dfa2", "lesson": 10, "level": "C3 · LOCUS", "q": "An auditor in country X negligently audits a company; a Singapore investor relies on the audit and loses money in Singapore. Where is the negligence tort located, per Vibrant Group?", "hint": "Negligence: the act.", "opts": [{"t": "Both, so both laws apply cumulatively", "why": "The test finds one single place.", "ok": false}, {"t": "Singapore, where reliance occurred", "why": "That is the rule for misrepresentation directed at the claimant.", "ok": false}, {"t": "Country X, where the negligent act was done; reliance weighs less in negligence", "why": "Correct.", "ok": true}, {"t": "Singapore, where the loss was felt", "why": "The place of damage may be fortuitous.", "ok": false}]}, "c3-08b642f1": {"id": "c3-08b642f1", "lesson": 10, "level": "C3 · LOCUS", "q": "A misrepresentation is received in India only because the claimant is based there, but relied on and acted on elsewhere. Is India the locus, per JIO?", "hint": "Fortuitous receipt.", "opts": [{"t": "Yes: receipt alone locates misrepresentation", "why": "Receipt and reliance together, unless fortuitous.", "ok": false}, {"t": "Yes, because the claimant is based there", "why": "That is exactly why it is fortuitous.", "ok": false}, {"t": "No: receipt there is fortuitous, so use the substance test", "why": "Correct.", "ok": true}, {"t": "The claimant chooses", "why": "The court locates the tort.", "ok": false}]}, "c3-e118d18e": {"id": "c3-e118d18e", "lesson": 10, "level": "C3 · EXCEPTION", "q": "What threshold does Rickshaw set for the flexible exception?", "hint": "Purely fortuitous.", "opts": [{"t": "The displaced law must be purely fortuitous, on clear and satisfying grounds, with the exception strictly applied", "why": "Correct.", "ok": true}, {"t": "The other law must simply be more favourable to the claimant", "why": "A more favourable law is not enough.", "ok": false}, {"t": "Any significant connection elsewhere suffices", "why": "That is <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>'s preferred reform, not the current test.", "ok": false}, {"t": "The court applies the proper law of the tort", "why": "That was rejected in Boys and Red Sea.", "ok": false}]}, "c3-2972bdc9": {"id": "c3-2972bdc9", "lesson": 10, "level": "C3 · EXCEPTION", "q": "In Red Sea, which law was displaced, and why?", "hint": "Hong Kong.", "opts": [{"t": "The lex fori (Hong Kong), whose only link was incorporation, so the claimant relied solely on Saudi law", "why": "Correct; all or virtually all factors pointed to Saudi Arabia.", "ok": true}, {"t": "Neither: Red Sea rejected the exception", "why": "Red Sea applied it.", "ok": false}, {"t": "Both, in favour of English law", "why": "Not Red Sea.", "ok": false}, {"t": "The lex loci delicti, because it denied the claim", "why": "That is the Boys v Chaplin pattern.", "ok": false}]}, "c3-2f95fb81": {"id": "c3-2f95fb81", "lesson": 10, "level": "C3 · AUTONOMY", "q": "Can a contract's choice of law clause govern a tort claim in Singapore?", "hint": "Open.", "opts": [{"t": "Yes, settled by Rickshaw", "why": "Rickshaw did not decide it; the clause there was conceded non-exclusive.", "ok": false}, {"t": "No, settled by Ong Ghee Soon", "why": "Ong Ghee Soon decided nothing on it.", "ok": false}, {"t": "Only for consumer contracts", "why": "Consumers are the case for protective mandatory rules, not autonomy.", "ok": false}, {"t": "It is an open question (Ong Ghee Soon); argue direct autonomy or the exception route", "why": "Correct; <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr> call it \"just a small step away\".", "ok": true}]}, "c3-6c75477b": {"id": "c3-6c75477b", "lesson": 10, "level": "C3 · RULE", "q": "What is Singapore's general choice of law rule for torts?", "hint": "Two limbs.", "opts": [{"t": "The law of the place of damage", "why": "That is Rome II Art 4(1).", "ok": false}, {"t": "The proper law of the tort", "why": "Rejected in Boys and Red Sea.", "ok": false}, {"t": "The lex loci delicti alone", "why": "That is the Australian / Canadian approach.", "ok": false}, {"t": "Double actionability subject to a flexible exception (Rickshaw)", "why": "Correct.", "ok": true}]}, "c3-83c971ad": {"id": "c3-83c971ad", "lesson": 10, "level": "C3 · RULE", "q": "Does limb (b) require the conduct to be a \"tort\" under the foreign law?", "hint": "Civil liability.", "opts": [{"t": "Yes, it must be a tort by that law's categories", "why": "Civil liability is enough.", "ok": false}, {"t": "No, any liability at all, even criminal", "why": "It must be civil liability (Boys v Chaplin).", "ok": false}, {"t": "Yes, and also a crime", "why": "Machado v Fontes's criminal-liability reading was abandoned.", "ok": false}, {"t": "No: any civil liability between the parties suffices, e.g. statutory or delictual (Ong Ghee Soon)", "why": "Correct (Art 41 SCO in Ong Ghee Soon).", "ok": true}]}, "c3-a8fe6fae": {"id": "c3-a8fe6fae", "lesson": 10, "level": "C3 · LOCAL", "q": "Does double actionability apply to a tort committed in Singapore?", "hint": "Rickshaw.", "opts": [{"t": "No: Singapore law alone applies to local torts", "why": "That is the rejected Metall rule.", "ok": false}, {"t": "Only for defamation", "why": "It applies to all torts.", "ok": false}, {"t": "Only if the defendant is foreign", "why": "It applies regardless.", "ok": false}, {"t": "Yes: Rickshaw rejected Metall's English-law-only rule, so both limbs run (both pointing to Singapore law)", "why": "Correct; the exception may apply foreign law only if Singapore is purely fortuitous.", "ok": true}]}, "c3-c7689659": {"id": "c3-c7689659", "lesson": 10, "level": "C3 · PROOF", "q": "The defendant does not plead the foreign lex loci delicti. What follows, per EFT Holdings?", "hint": "Not pleaded.", "opts": [{"t": "The flexible exception applies automatically", "why": "Not automatically.", "ok": false}, {"t": "No conflicts issue arises and Singapore law applies", "why": "Correct.", "ok": true}, {"t": "The claim fails for want of proof of foreign law", "why": "The defendant bears limb (b); not pleading it means Singapore law applies.", "ok": false}, {"t": "The court applies the foreign law presumed similar", "why": "The presumption applies to pleaded but unproved law.", "ok": false}]}, "c3-972689e4": {"id": "c3-972689e4", "lesson": 10, "level": "C3 · STATUTE", "q": "What does THPA s 6(4) do?", "hint": "Limb 2 abrogated.", "opts": [{"t": "Bars haze claims by foreigners", "why": "Claimants must suffer loss in Singapore, but nationality is irrelevant.", "ok": false}, {"t": "Makes haze-causing conduct actionable whether or not it is actionable abroad: an express statutory displacement of limb 2", "why": "Correct.", "ok": true}, {"t": "Locates every haze tort abroad", "why": "The opposite effect.", "ok": false}, {"t": "Applies the flexible exception to haze claims", "why": "It is a statutory displacement, not the exception.", "ok": false}]}, "c3-5a113b0f": {"id": "c3-5a113b0f", "lesson": 10, "level": "C3 · CONTRACT", "q": "Per <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr> (North), how should an exemption clause raised against a tort claim be analysed?", "hint": "Two questions.", "opts": [{"t": "Only under the law closest to the issue", "why": "That is Lord Denning, criticised.", "ok": false}, {"t": "Only under the contract's proper law", "why": "That is the Sayers majority, criticised as simplistic.", "ok": false}, {"t": "Admissibility as a tort question (double actionability) and validity as a contract question (its proper law)", "why": "Correct (Kahn-Freund; North).", "ok": true}, {"t": "Only under Singapore law", "why": "The lex loci delicti and proper law also matter.", "ok": false}]}, "c3-0643e905": {"id": "c3-0643e905", "lesson": 10, "level": "C3 · LIMITATION", "q": "The flexible exception displaces the lex loci delicti so that only Singapore law governs. Which limitation period applies?", "hint": "Single lex causae.", "opts": [{"t": "None", "why": "A period always applies.", "ok": false}, {"t": "Both periods cumulatively", "why": "That is the UK s 1(2) position.", "ok": false}, {"t": "Singapore's Limitation Act, as the single lex causae's period", "why": "Correct (<abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>; the Boys pattern).", "ok": true}, {"t": "The lex loci delicti's period, always", "why": "Only while it is a lex causae.", "ok": false}]}, "c3-6079b2f9": {"id": "c3-6079b2f9", "lesson": 10, "level": "C3 · EVALUATION", "q": "Which is a criticism of double actionability's lex fori limb?", "hint": "Parochial.", "opts": [{"t": "It is \"parochial\", born of tort's criminal-law roots, with no forum-connection requirement", "why": "Correct (Red Sea; <abbr title=\"Chong &amp; Yip, the course textbook\">C&amp;Y</abbr>).", "ok": true}, {"t": "It ignores the place of the tort", "why": "That is limb (b)'s job.", "ok": false}, {"t": "It makes the defendant prove too much", "why": "That concerns the burden, not the parochialism critique.", "ok": false}, {"t": "It was invented by Rome II", "why": "It comes from The Halley and Phillips v Eyre.", "ok": false}]}};
window.LESSONS={"0": {"title": "How conflict of laws works, and how to use the router", "short": "Start here", "file": "start.html", "code": "00"}, "1": {"title": "Clause triage: what the jurisdiction clause promises, and the CCAA", "short": "Clause triage and the CCAA", "file": "j1.html", "code": "J1"}, "2": {"title": "Existence when the defendant is in Singapore: service in and submission", "short": "Service in and submission", "file": "j2.html", "code": "J2"}, "3": {"title": "Existence when the defendant is abroad: service out", "short": "Service out", "file": "j3.html", "code": "J3"}, "4": {"title": "Exercise: Spiliada, forum conveniens and strong cause", "short": "Spiliada and strong cause", "file": "j4.html", "code": "J4"}, "5": {"title": "The SICC: written agreements, transfer and joinder", "short": "SICC", "file": "j5.html", "code": "J5"}, "6": {"title": "Anti-suit injunctions: stopping a party suing abroad", "short": "Anti-suit injunctions", "file": "j6.html", "code": "J6"}, "7": {"title": "Foreign judgments: enforcement, recognition and AEIs", "short": "Foreign judgments", "file": "j7.html", "code": "J7"}, "8": {"title": "Choice of law methodology: characterise, connect, apply", "short": "Choice of law methodology", "file": "c1.html", "code": "C1"}, "9": {"title": "Contract choice of law: the proper law and illegality", "short": "Contract choice of law", "file": "c2.html", "code": "C2"}, "10": {"title": "Tort choice of law: double actionability and the flexible exception", "short": "Tort choice of law", "file": "c3.html", "code": "C3"}};
